const NIVEIS_ACADEMIA=[
  {min:0,titulo:"Iniciante"},{min:200,titulo:"Aprendiz"},{min:500,titulo:"Empresário em Formação"},
  {min:1000,titulo:"Empresário Estruturado"},{min:2000,titulo:"Empresário Estratégico"},
  {min:4000,titulo:"Empresário Mestre"},
];
function calcularNivelAcademia(xp){
  let atual=NIVEIS_ACADEMIA[0],idx=0;
  for(let i=0;i<NIVEIS_ACADEMIA.length;i++){if(xp>=NIVEIS_ACADEMIA[i].min){atual=NIVEIS_ACADEMIA[i];idx=i;}}
  const prox=NIVEIS_ACADEMIA[idx+1];
  const progresso=prox?Math.round(((xp-atual.min)/(prox.min-atual.min))*100):100;
  return{titulo:atual.titulo,indice:idx,progresso,proximoMin:prox?prox.min:null};
}
// Contabiliza um dia de estudo (mantém sequência se foi ontem, reseta se pulou um dia).
function registrarEstudoAcademia(academia){
  const hj=hoje();
  if(academia.ultimoEstudo===hj)return academia;
  const ontem=(()=>{const d=new Date();d.setDate(d.getDate()-1);return d.toISOString().slice(0,10);})();
  const dias=academia.ultimoEstudo===ontem?(academia.diasConsecutivos||0)+1:1;
  return{...academia,diasConsecutivos:dias,ultimoEstudo:hj};
}

