// Mapeia status antigos para os status atuais do app, sem perder nenhum pedido
const STATUS_MIGRACAO={
  "Produzir":"A Fazer","produzir":"A Fazer",
  "Entregar":"Pedido Feito","entregar":"Pedido Feito",
  "Enviado":"Entregue","enviado":"Entregue",
  "Atrasado":"Cancelado","atrasado":"Cancelado",
};
function migrarDB(db){
  const out={...DB0,...db};
  out.pedidos=(out.pedidos||[]).map(p=>({
    ...p,
    status: ST_PEDIDO.includes(p.status) ? p.status : (STATUS_MIGRACAO[p.status]||"A Fazer"),
  }));
  out.caixa=out.caixa||[];
  out.clientes=Array.isArray(out.clientes)?out.clientes.map(c=>c.estagioComercial?c:
    {...c,estagioComercial:pedidosDoCliente(c,out.pedidos||[]).length>0?"Cliente":"Interessado"}):[];
  if(!out.academia||!Array.isArray(out.academia.modulos)){
    out.academia={...DB0.academia};
  } else {
    const nomesExistentes=out.academia.modulos.map(m=>m.nome);
    const faltantes=TRILHA_ACADEMIA_BASE.filter(m=>!nomesExistentes.includes(m.nome));
    out.academia={xp:out.academia.xp||0,diasConsecutivos:out.academia.diasConsecutivos||0,
      ultimoEstudo:out.academia.ultimoEstudo||null,tempoTotalMin:out.academia.tempoTotalMin||0,
      modulos:[...out.academia.modulos,...faltantes]};
  }
  // Migra tarefas do formato antigo (feita/prioridade/data) pro novo modelo do Work
  // (status/urgência/prazo/categoria/responsável), remapeia áreas antigas pro novo
  // conjunto fixo de 7 áreas, e garante o campo de recorrência em tarefas antigas.
  out.tarefas=(out.tarefas||[]).map(t=>{
    let novo=t;
    if(!STATUS_WORK.includes(t.status)){
      novo={
        id:t.id,titulo:t.titulo||"",descricao:t.descricao||"",
        categoria:MAP_CATEGORIA_TAREFA_ANTIGA[t.categoria]||"Operacional",
        urgencia:t.prioridade==="Alta"?"Alta":t.prioridade==="Baixa"?"Baixa":"Média",
        prazo:t.data||hoje(),
        status:t.feita?"Concluído":"Pendente",
        responsavel:t.responsavel||"",
      };
    }
    if(!CATEGORIAS_WORK.includes(novo.categoria)){
      novo={...novo,categoria:MAP_AREA_WORK_V1_V2[novo.categoria]||"Operacional"};
    }
    if(!RECORRENCIAS_WORK.includes(novo.recorrencia)){
      novo={...novo,recorrencia:"Nenhuma",recorrenciaDias:novo.recorrenciaDias||null};
    }
    // Campos novos (objetivo, projeto relacionado, favorito, override de Central,
    // próxima ação, histórico) — tarefa antiga que nunca teve isso ganha o padrão.
    if(novo.historico===undefined){
      novo={...novo,objetivo:novo.objetivo||"",projetoRelacionado:novo.projetoRelacionado||"",
        favorito:!!novo.favorito,mostrarNaCentral:!!novo.mostrarNaCentral,proximaAcao:novo.proximaAcao||"",
        observacoes:novo.observacoes||"",etapas:novo.etapas||[],
        historico:[{data:novo.criadoEm||hoje(),texto:"Atividade criada"}]};
    }
    return novo;
  });
  // Seed único: projeto "Reativação do Grupo", pedido explicitamente pelo
  // Fabrício. Usa o mesmo sistema de Objetivo/Etapas do Work — não cria nada
  // paralelo. Roda só uma vez (confere por origemKey antes de criar).
  if(!out.tarefas.some(t=>t.origemKey==="seed-reativacao-grupo")){
    const proxId=(out.tarefas.reduce((m,t)=>Math.max(m,t.id),0)||out.nextId||100)+1;
    const et=(id,titulo,porque)=>({id,titulo,porque,concluida:false});
    out.tarefas=[...out.tarefas,{
      id:proxId,titulo:"📣 Reativação do Grupo",
      descricao:"Transformar o grupo do WhatsApp de vitrine parada em canal de vendas de verdade.",
      objetivo:"Interação → Interesse → Conversa → Venda → Pós-venda → Recompra",
      categoria:"Marketing",urgencia:"Alta",prazo:hoje(),status:"Pendente",responsavel:"",
      recorrencia:"Nenhuma",recorrenciaDias:null,projetoRelacionado:"",mostrarNaCentral:false,
      favorito:false,proximaAcao:"",observacoes:"",criadoEm:hoje(),origemKey:"seed-reativacao-grupo",
      historico:[{data:hoje(),texto:"Objetivo criado"}],
      etapas:[
        et(1,"Criar enquete de futebol","Enquete é o jeito mais fácil de fazer alguém parado interagir"),
        et(2,"Criar batalha (times/jogadores)","Batalha gera comentário e engajamento maior que post comum"),
        et(3,"Publicar conteúdo de futebol","Mantém o grupo vivo entre uma venda e outra"),
        et(4,"Publicar produto relacionado ao assunto","Conecta o interesse por futebol com o que você vende"),
        et(5,"Identificar pessoas interessadas","Sem saber quem reagiu, não tem quem abordar depois"),
        et(6,"Fazer follow-up no privado","A venda acontece na conversa individual, não no grupo"),
        et(7,"Registrar interessados no CRM","Se não registrar, esquece e perde a venda depois"),
        et(8,"Registrar vendas geradas","É o que prova se a ação de marketing funcionou"),
        et(9,"Avaliar resultado","Decide se repete a mesma tática ou tenta outra"),
      ],
    }];
  }
  out.pedidosFornecedor=out.pedidosFornecedor||[];
  out.meta={...DB0.meta,...(out.meta||{})};
  out.centralComando={...DB0.centralComando,...(out.centralComando||{})};
  // Compat: quem já tinha "próxima ação" como texto único (versão anterior) migra
  // automaticamente para a fila, sem perder o que já estava escrito. Só usa o valor
  // padrão quando a fila nunca existiu — fila vazia por ter concluído tudo é válida.
  if(!Array.isArray(out.centralComando.filaAcoes)){
    out.centralComando.filaAcoes=out.centralComando.proximaAcao
      ?[out.centralComando.proximaAcao]:[...DB0.centralComando.filaAcoes];
  }
  delete out.centralComando.proximaAcao;
  if(!Array.isArray(out.calendarioComercial)||out.calendarioComercial.length!==7){
    out.calendarioComercial=[...DB0.calendarioComercial];
  }
  out.checkins=(out.checkins&&typeof out.checkins==="object"&&!Array.isArray(out.checkins))?out.checkins:{};
  out.ecossistema=(out.ecossistema&&Array.isArray(out.ecossistema.projetos))?out.ecossistema:DB0.ecossistema;
  out.nextId=out.nextId||100;
  return out;
}

function loadDB(){
  try{
    const r=localStorage.getItem(DB_KEY);
    if(r)return migrarDB(JSON.parse(r));
  }catch(_){}
  // Fallback: procura em chaves antigas conhecidas, caso a principal esteja vazia
  for(const k of DB_KEY_LEGACY_CANDIDATES){
    try{
      const r=localStorage.getItem(k);
      if(r)return migrarDB(JSON.parse(r));
    }catch(_){}
  }
  const db=JSON.parse(JSON.stringify(DB0));db.produtos=estoqueInicial();return db;
}
function saveDB(db){try{localStorage.setItem(DB_KEY,JSON.stringify(db));}catch(_){}}

