// ── ESTOQUE ──────────────────────────────────────────────────
function PageEstoque({db,onAdd,onEdit,onDelete}){
  const [busca,setBusca]=useState("");const [ft,setFt]=useState("Todos");
  const total=db.produtos.reduce((a,p)=>a+p.qtd,0);
  const valor=db.produtos.reduce((a,p)=>a+p.qtd*(p.custoProduto||0),0);
  // Chave normalizada — só para AGRUPAR/COMPARAR. O que aparece na tela continua
  // exatamente como foi digitado no cadastro. Ignora: espaço extra, maiúscula/minúscula,
  // ano embutido no nome (item antigo) e as palavras "Feminina"/"Retrô" fora de parênteses
  // — assim "Vitória", "Vitória 2025 Feminina" e "Vitória Retrô" caem no mesmo grupo.
  // Conteúdo ENTRE parênteses (ex: "(Barbearia)", "(Pai)", "(Juan)") nunca é tocado —
  // esses continuam formando grupos separados de propósito.
  const norm=(s)=>{
    const original=(s||"").trim();
    const parenMatch=original.match(/\([^)]*\)/);
    const parenPart=parenMatch?parenMatch[0].toLowerCase().replace(/\s+/g," "):"";
    const semParen=original.replace(/\([^)]*\)/g,"").trim();
    const limpo=semParen
      .replace(/\b(19|20)\d{2}\b/g,"")
      .replace(/(?<=^|\s)feminin[oa]s?(?=\s|$)/gi,"")
      .replace(/(?<=^|\s)retr[oô]s?(?=\s|$)/gi,"")
      .replace(/\s+/g," ")
      .trim()
      .toLowerCase();
    return (limpo+(parenPart?" "+parenPart:"")).trim();
  };
  // Posição dentro do grupo: Uniforme 1 primeiro, Uniforme 2 depois, Retrô em seguida,
  // "Feminina" sempre por último. Usa os campos estruturados quando existirem; para itens
  // antigos (cadastrados antes desses campos existirem), cai de volta para procurar a
  // palavra no nome, como fallback.
  const tipoRank=(p)=>{
    const texto=`${p.time||""} ${p.nome||""} ${p.uniforme||""}`.toLowerCase();
    const fem=p.feminina===true||(p.feminina===undefined&&texto.includes("feminin"));
    const retro=p.retro===true||(p.retro===undefined&&texto.includes("retr"));
    if(fem)return 3;
    if(retro)return 2;
    if((p.uniforme||"").toLowerCase().includes("2"))return 1;
    return 0;
  };
  const nomesOriginais=new Map(); // normalizado -> nome original mais "genérico" pra representar o grupo
  db.produtos.forEach(p=>{
    const nomeOriginal=(p.time||p.nome||"").trim();
    if(!nomeOriginal)return;
    const key=norm(nomeOriginal);
    const generico=!/\(|feminin|retr[oô]/i.test(nomeOriginal);
    if(!nomesOriginais.has(key)||generico)nomesOriginais.set(key,nomeOriginal);
  });
  const times=["Todos",...nomesOriginais.values()]
    .sort((a,b)=>a==="Todos"?-1:b==="Todos"?1:a.localeCompare(b,"pt-BR"));
  const filtrados=db.produtos.filter(p=>
    (!busca||(p.time||p.nome||"").toLowerCase().includes(busca.toLowerCase())
      ||p.tamanho?.toLowerCase().includes(busca.toLowerCase())
      ||(p.cor||"").toLowerCase().includes(busca.toLowerCase()))
    &&(ft==="Todos"||norm(p.time||p.nome)===norm(ft)))
    .sort((a,b)=>{
      const na=norm(a.time||a.nome);
      const nb=norm(b.time||b.nome);
      if(na<nb)return -1;if(na>nb)return 1;
      // Mesmo grupo: ano mais recente primeiro
      const anoA=Number(a.ano)||0,anoB=Number(b.ano)||0;
      if(anoA!==anoB)return anoB-anoA;
      // Depois: Uniforme 1 → Uniforme 2 → Feminina
      const ra=tipoRank(a),rb=tipoRank(b);
      if(ra!==rb)return ra-rb;
      const ORDER=["PP","P","M","G","GG","XGG","3G","4G"];
      return ORDER.indexOf(a.tamanho)-ORDER.indexOf(b.tamanho);
    });

  const IC = {width:32,height:32,borderRadius:7,border:"1px solid #e5e7eb",background:"#f9fafb",
    cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:"#374151"};
  const IC_DEL = {...IC,border:"1px solid #fecaca",background:"#fef2f2",color:"#dc2626"};

  return(
    <div>
      {/* KPIs — apenas o essencial */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:14,marginBottom:20}}>
        <KPI label="📦 Total em Estoque" value={`${total} peça${total!==1?"s":""}`}/>
        <KPI label="💰 Valor em Estoque" value={brl(valor)}/>
      </div>

      <Section>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",
          marginBottom:14,flexWrap:"wrap",gap:10}}>
          <div style={{fontWeight:800,fontSize:15,color:"#111"}}>
            {filtrados.length} camisa{filtrados.length!==1?"s":""}
          </div>
          <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
            <Tabs options={times.map(t=>({k:t,l:t}))} value={ft} onChange={setFt}/>
            <Inp value={busca} onChange={e=>setBusca(e.target.value)}
              placeholder="Buscar..." style={{...INP,width:160}}/>
            <Btn onClick={onAdd}>+ Camisa</Btn>
          </div>
        </div>

        {filtrados.length===0?<Empty msg="Nenhuma camisa encontrada." icon="👕"/>:(
          <div style={{overflowX:"auto"}}>
            <table style={{width:"100%",borderCollapse:"collapse"}}>
              <thead>
                <tr>{["Time / Camisa","Uniforme","Ano","Tam.","Cor","Custo","Qtd",""].map(h=>
                  <th key={h} style={TH}>{h}</th>)}
                </tr>
              </thead>
              <tbody>
                {(()=>{
                  const rows=[];
                  let lastKey=null;
                  filtrados.forEach(p=>{
                    const teamName=(p.time||p.nome||"Sem time").trim();
                    const key=norm(teamName);
                    if(key!==lastKey){
                      lastKey=key;
                      const count=filtrados.filter(x=>norm(x.time||x.nome||"Sem time")===key).length;
                      rows.push(
                        <tr key={`grupo-${key}`}>
                          <td colSpan={8} style={{padding:"9px 14px 7px",background:"#faf7f8",
                            borderTop:"1px solid #f0e6e9",borderBottom:"1px solid #f0e6e9"}}>
                            <span style={{fontWeight:800,fontSize:12,color:"#5c2030",
                              textTransform:"uppercase",letterSpacing:"0.4px"}}>{teamName}</span>
                            <span style={{marginLeft:8,fontSize:11,color:"#9ca3af",fontWeight:600}}>
                              {count} {count===1?"item":"itens"}
                            </span>
                          </td>
                        </tr>
                      );
                    }
                    const ct=r((p.custoProduto||0)+(p.custoTaxa||0));
                    const zero=p.qtd===0;
                    rows.push(
                      <HRow key={p.id}>
                        <td style={TD}>
                          <div style={{fontWeight:700,color:"#111",fontSize:13}}>
                            {p.time||p.nome}{p.ano&&<span style={{color:"#9ca3af",fontWeight:400}}> {p.ano}</span>}
                            {p.retro&&<span style={{marginLeft:6,fontSize:10,fontWeight:700,color:"#92400e",
                              background:"#fffbeb",padding:"2px 7px",borderRadius:20}}>Retrô</span>}
                            {p.feminina&&<span style={{marginLeft:6,fontSize:10,fontWeight:700,color:"#be185d",
                              background:"#fdf2f7",padding:"2px 7px",borderRadius:20}}>Feminina</span>}
                          </div>
                        </td>
                        <td style={{...TD,color:"#6b7280",fontSize:12}}>{p.uniforme||"—"}</td>
                        <td style={{...TD,color:"#6b7280",fontSize:12}}>{p.ano||"—"}</td>
                        <td style={{...TD,fontWeight:600}}>{p.tamanho}</td>
                        <td style={{...TD,color:"#6b7280",fontSize:12}}>{p.cor||"—"}</td>
                        <td style={TD}>{brl(ct)}</td>
                        <td style={TD}>
                          <span style={{fontWeight:800,fontSize:15,
                            color:zero?"#dc2626":"#16a34a"}}>
                            {p.qtd}
                          </span>
                        </td>
                        <td style={TD}>
                          <div style={{display:"flex",gap:5}}>
                            <button onClick={()=>onEdit(p)} title="Editar" style={IC}>
                              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4z"/></svg>
                            </button>
                            <button onClick={()=>onDelete(p.id)} title="Excluir" style={IC_DEL}>
                              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg>
                            </button>
                          </div>
                        </td>
                      </HRow>
                    );
                  });
                  return rows;
                })()}
              </tbody>
            </table>
          </div>
        )}
      </Section>
    </div>
  );
}

// Seção colapsável de pedidos para estoque (Opção B)
function EstoqueColapsavel({pedidos,onEdit,onDelete}){
  const [aberto,setAberto]=useState(false);
  const [h,setH]=useState(false);
  return(
    <div style={{background:"#fff",border:"1px solid #e5e7eb",borderRadius:12,marginBottom:16,overflow:"hidden"}}>
      <div onClick={()=>setAberto(a=>!a)} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
        style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"14px 20px",
          cursor:"pointer",background:h?"#f9fafb":"#fff",transition:"background 0.15s",
          borderBottom:aberto?"1px solid #e5e7eb":"none"}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:16}}>📦</span>
          <span style={{fontWeight:700,fontSize:14,color:"#374151"}}>Pedidos para Estoque</span>
          <span style={{background:"#ecfdf5",color:"#065f46",border:"1px solid #6ee7b7",
            padding:"2px 10px",borderRadius:20,fontSize:12,fontWeight:700}}>{pedidos.length}</span>
        </div>
        <span style={{fontSize:18,color:"#9ca3af",transition:"transform 0.2s",
          transform:aberto?"rotate(180deg)":"none"}}>⌄</span>
      </div>
      {aberto&&(
        <div style={{overflowX:"auto",padding:"0 0 4px"}}>
          <table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead><tr>{["Data","ID","Camisa","Tamanho","Custo","Status",""].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
            <tbody>
              {pedidos.map(p=>{
                const c=r(((p.custoProduto||0)+(p.custoTaxa||0))*(p.qtd||1));
                return(
                  <HRow key={p.id}>
                    <td style={{...TD,color:"#9ca3af"}}>{fmtData(p.data)}</td>
                    <td style={{...TD,color:"#9ca3af",fontSize:12}}>#{p.id}</td>
                    <td style={TD}><div style={{fontWeight:600,color:"#374151"}}>{p.time||p.camisa}{p.ano&&` ${p.ano}`}</div></td>
                    <td style={TD}>{p.tamanho}</td>
                    <td style={TD}>{brl(c)}</td>
                    <td style={TD}><Badge status={p.status}/></td>
                    <td style={TD}><div style={{display:"flex",gap:5}}>
                      <button onClick={()=>onEdit(p)} title="Editar" style={{width:32,height:32,borderRadius:7,border:"1px solid #e5e7eb",background:"#f9fafb",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:"#374151"}}>
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4z"/></svg>
                      </button>
                      <button onClick={()=>onDelete(p.id)} title="Excluir" style={{width:32,height:32,borderRadius:7,border:"1px solid #fecaca",background:"#fef2f2",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:"#dc2626"}}>
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg>
                      </button>
                    </div></td>
                  </HRow>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// ── PEDIDOS ──────────────────────────────────────────────────
function PagePedidos({db,onAdd,onEdit,onDelete,onUpdateMeta,statusInicial,mesInicial}){
  const [filtro,setFiltro]=useState("mes");const [busca,setBusca]=useState("");
  const [statusFiltro,setStatusFiltro]=useState(statusInicial||"todos");
  const [mesFiltro,setMesFiltro]=useState(""); // "" = usa o filtro de período acima
  const [mm,setMm]=useState(false);const [mt,setMt]=useState({...db.meta});
  const m=mesAtual();const hj=hoje();const sw=semIni();const mp=mesPrev();

  // Gera lista de meses com pedidos (últimos 12 meses + meses que têm pedido)
  const mesesDisponiveis=useMemo(()=>{
    const set=new Set();
    // Últimos 12 meses
    for(let i=0;i<12;i++){
      const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);
      set.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`);
    }
    // Meses de pedidos existentes
    db.pedidos.forEach(p=>{if(p.data)set.add(p.data.slice(0,7));});
    return [...set].sort().reverse();
  },[db.pedidos]);

  // Quando chega um status específico vindo do Dashboard (e opcionalmente um mês, ex: card Entregue)
  useEffect(()=>{
    if(statusInicial){
      setStatusFiltro(statusInicial==="__atrasados__"?"__atrasados__":statusInicial);
      if(mesInicial){setMesFiltro(mesInicial);}
      else{setFiltro("todos");setMesFiltro("");}
    }
  },[statusInicial,mesInicial]);

  const filtrados=db.pedidos.filter(p=>{
    let mf;
    if(mesFiltro){mf=p.data?.startsWith(mesFiltro);}
    else{mf=filtro==="todos"?true:filtro==="hoje"?p.data===hj:filtro==="semana"?p.data>=sw:filtro==="mes_ant"?p.data?.startsWith(mp):p.data?.startsWith(m);}
    const sf=statusFiltro==="todos"?true:statusFiltro==="__atrasados__"?isAtrasado(p):statusFiltro==="__estoque__"?isEstoque(p):p.status===statusFiltro;
    return mf&&sf&&(!busca||p.cliente?.toLowerCase().includes(busca.toLowerCase())||p.time?.toLowerCase().includes(busca.toLowerCase())||p.camisa?.toLowerCase().includes(busca.toLowerCase()));
  });

  // Separar vendas de estoque
  const filtradosVendas=filtrados.filter(p=>!isEstoque(p));
  const filtradosEstoque=filtrados.filter(p=>isEstoque(p));

  // Ordenar por prioridade:
  // 1. A Fazer (produzir) | 2. Atrasado | 3. Em Transporte | 4. Pedido Feito
  // 5. Entregue com saldo pendente (cobrar) | 6. Concluído (entregue + pago)
  const prioridade=(p)=>{
    if(p.status==="A Fazer"&&isAtrasado(p))return 1;
    if(p.status==="A Fazer")return 2;
    if(p.status==="Em Transporte")return 3;
    if(p.status==="Pedido Feito")return 4;
    const sb=r((p.precoVenda||0)-(p.valorRecebido||0));
    if(p.status==="Entregue"&&sb>0)return 5;
    return 6; // concluído
  };
  const vendaOrdenada=[...filtradosVendas].sort((a,b)=>prioridade(a)-prioridade(b));

  const mesKPI=mesFiltro||m;
  const pm=db.pedidos.filter(p=>p.data?.startsWith(mesKPI)&&!isEstoque(p));
  const fat=pm.reduce((a,p)=>a+(p.precoVenda||0)*(p.qtd||1),0);
  const cus=pm.reduce((a,p)=>a+((p.custoProduto||0)+(p.custoTaxa||0))*(p.qtd||1),0);
  const luc=r(fat-cus);const rec=pm.reduce((a,p)=>a+(p.valorRecebido||0),0);
  const marg=fat>0?r((luc/fat)*100):0;
  const lucAtual=r(rec-cus);
  const margAtual=rec>0?r(((rec-cus)/rec)*100):null;
  const nomeMesKPI=(()=>{const [ano,mesN]=mesKPI.split("-");const n=new Date(Number(ano),Number(mesN)-1,1).toLocaleDateString("pt-BR",{month:"long",year:"numeric"});return n.charAt(0).toUpperCase()+n.slice(1);})();
  const FILTROS=[{k:"hoje",l:"Hoje"},{k:"semana",l:"Esta semana"},{k:"mes",l:"Este mês"},{k:"mes_ant",l:"Mês passado"},{k:"todos",l:"Todos"}];
  const FILTROS_STATUS=[
    {k:"todos",l:"Todos os status"},
    {k:"__atrasados__",l:"⚠ Atrasados (+7 dias)"},
    {k:"__estoque__",l:"📦 Pedidos de Estoque"},
    ...ST_PEDIDO.map(s=>({k:s,l:s}))
  ];
  return(
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}>
        <div style={{fontSize:22,fontWeight:800,color:"#111"}}>Pedidos</div>
        <div style={{display:"flex",gap:8}}><Btn v="sec" onClick={()=>{setMt({...db.meta});setMm(true);}}>🎯 Meta</Btn><Btn onClick={onAdd}>+ Pedido</Btn></div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(5,minmax(0,1fr))",gap:12,marginBottom:12}}>
        <KPI label={`Pedidos ${nomeMesKPI.split(" ")[0]}`} value={pm.length} dark/>
        <KPI label="Faturamento" value={brl(fat)} color="#16a34a"/>
        <KPI label="Custo" value={brl(cus)} color="#dc2626"/>
        <KPI label="Lucro Líquido" value={brl(luc)} color={luc>=0?"#16a34a":"#dc2626"}/>
        <KPI label="Margem Projetada" value={pct(marg)} color={marg>=30?"#16a34a":marg>=15?"#ca8a04":"#dc2626"}/>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(5,minmax(0,1fr))",gap:12,marginBottom:16}}>
        <KPI label="Recebido"     value={brl(rec)} color="#16a34a"/>
        <KPI label="Lucro Atual"  value={brl(lucAtual)} color={lucAtual>=0?"#16a34a":"#dc2626"}/>
        <KPI label="Margem Atual" value={margAtual===null?"—":pct(margAtual)}
          color={margAtual===null?"#9ca3af":margAtual>=30?"#16a34a":margAtual>=15?"#ca8a04":"#dc2626"}/>
        <KPI label="A Receber"    value={brl(r(fat-rec))} color={fat-rec>0?"#ca8a04":"#16a34a"}/>
        <KPI label="Ticket Médio" value={brl(pm.length>0?r(fat/pm.length):0)}/>
      </div>
      {(()=>{
        const metas=[{l:"Pedidos",a:pm.length,m:db.meta.pedidos,f:v=>String(v)},
          {l:"Faturamento",a:fat,m:db.meta.receita,f:brl}].filter(x=>x.m>0);
        if(metas.length===0)return null;
        return(
          <Section title={`🎯 Meta de ${nomeMesKPI}`}>
            <div style={{display:"grid",gridTemplateColumns:`repeat(${metas.length},minmax(0,1fr))`,gap:20}}>
              {metas.map(({l,a,m:mv,f})=>{
                const p=mv>0?Math.min(100,(a/mv)*100):0;
                return(<div key={l}><div style={{display:"flex",justifyContent:"space-between",fontSize:12,color:"#6b7280",marginBottom:2}}><span>{l}: <strong>{f(a)}</strong> / {f(mv)}</span><span style={{fontWeight:700}}>{p.toFixed(0)}%</span></div><Prog value={Math.max(0,a)} max={mv} color="#111"/></div>);
              })}
            </div>
          </Section>
        );
      })()}
      {(statusFiltro!=="todos")&&(
        <Alert type="info">
          {statusFiltro==="__atrasados__"
            ?"⚠ Mostrando pedidos atrasados (A Fazer há mais de 7 dias)"
            :<>Mostrando pedidos com status <strong>{statusFiltro}</strong></>}
          <button onClick={()=>setStatusFiltro("todos")} style={{marginLeft:"auto",border:"none",
            background:"none",cursor:"pointer",fontWeight:700,color:"#2563eb",fontSize:12}}>Limpar filtro</button>
        </Alert>
      )}
      {mesFiltro&&(
        <Alert type="info">
          📅 Filtrando por {(()=>{const[ano,mesN]=mesFiltro.split("-");const n=new Date(Number(ano),Number(mesN)-1,1).toLocaleDateString("pt-BR",{month:"long",year:"numeric"});return n.charAt(0).toUpperCase()+n.slice(1);})()}
          <button onClick={()=>setMesFiltro("")} style={{marginLeft:"auto",border:"none",
            background:"none",cursor:"pointer",fontWeight:700,color:"#2563eb",fontSize:12}}>Limpar</button>
        </Alert>
      )}
      <Section action={
        <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
          {!mesFiltro&&<Tabs options={FILTROS} value={filtro} onChange={setFiltro}/>}
          <select value={mesFiltro} onChange={e=>{setMesFiltro(e.target.value);if(e.target.value)setFiltro("todos");}}
            style={{...INP,width:150,padding:"6px 10px",fontSize:12}}>
            <option value="">Por mês ▾</option>
            {mesesDisponiveis.map(mes=>{
              const [ano,mesN]=mes.split("-");
              const nome=new Date(Number(ano),Number(mesN)-1,1).toLocaleDateString("pt-BR",{month:"long",year:"numeric"});
              return<option key={mes} value={mes}>{nome.charAt(0).toUpperCase()+nome.slice(1)}</option>;
            })}
          </select>
          <select value={statusFiltro} onChange={e=>setStatusFiltro(e.target.value)}
            style={{...INP,width:190,padding:"6px 10px",fontSize:12}}>
            {FILTROS_STATUS.map(s=><option key={s.k} value={s.k}>{s.l}</option>)}
          </select>
          <Inp value={busca} onChange={e=>setBusca(e.target.value)} placeholder="Buscar..." style={{...INP,width:160}}/>
        </div>
      }>
        <div style={{fontWeight:800,fontSize:15,color:"#111",marginBottom:14}}>
          Pedidos {vendaOrdenada.length>0&&<span style={{color:"#9ca3af",fontWeight:400,fontSize:13}}>({vendaOrdenada.length})</span>}
        </div>
        {vendaOrdenada.length===0?<Empty msg="Nenhum pedido encontrado." icon="🛒"/>:(
          <div style={{width:"100%"}}>
            <table style={{width:"100%",borderCollapse:"collapse",tableLayout:"fixed"}}>
              <colgroup>
                <col style={{width:"7%"}}/><col style={{width:"13%"}}/><col style={{width:"18%"}}/>
                <col style={{width:"9%"}}/><col style={{width:"9%"}}/><col style={{width:"9%"}}/>
                <col style={{width:"8%"}}/><col style={{width:"8%"}}/><col style={{width:"11%"}}/>
                <col style={{width:"8%"}}/>
              </colgroup>
              <thead><tr>{["Data","Cliente","Produto","Custo","Vendido","A Receber","Lucro","Margem","Status",""].map(h=>
                <th key={h} style={h==="A Receber"?{...TH,color:"#dc2626"}:TH}>{h}</th>)}</tr></thead>
              <tbody>
                {vendaOrdenada.map(p=>{
                  const v=r((p.precoVenda||0)*(p.qtd||1));const c=r(((p.custoProduto||0)+(p.custoTaxa||0))*(p.qtd||1));
                  const l=r(v-c);const sb=r(v-(p.valorRecebido||0));
                  const recebido=p.valorRecebido||0;
                  // Margem realista: baseada só no que já entrou de fato (não no valor total da venda)
                  const margemRecebida=recebido>0?r(((recebido-c)/recebido)*100):null;
                  const concluido=p.status==="Entregue"&&sb<=0;
                  return(
                    <HRow key={p.id}>
                      <td style={{...TD,color:"#9ca3af",whiteSpace:"nowrap"}}>{fmtData(p.data)}</td>
                      <td style={{...TD,verticalAlign:"top"}}>
                        <div style={{display:"flex",alignItems:"center",gap:6,overflow:"hidden"}}>
                          {concluido&&(
                            <span style={{width:16,height:16,borderRadius:"50%",background:"#16a34a",
                              display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                              <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#fff"
                                strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round">
                                <polyline points="20 6 9 17 4 12"/>
                              </svg>
                            </span>
                          )}
                          <div style={{fontWeight:700,color:"#111",fontSize:13,
                            overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{p.cliente}</div>
                        </div>
                        {p.captacao&&<div style={{fontSize:10.5,color:"#9ca3af",marginTop:2}}>Captação: {p.captacao}</div>}
                      </td>
                      <td style={{...TD,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                        {p.time||p.camisa}{p.ano&&` ${p.ano}`} {p.uniforme&&`(${p.uniforme})`} · {p.tamanho}
                        {(p.qtd||1)>1&&<span style={{color:"#9ca3af"}}> · Qtd {p.qtd}</span>}
                      </td>
                      <td style={{...TD,color:"#dc2626",whiteSpace:"nowrap"}}>{brl(c)}</td>
                      <td style={{...TD,fontWeight:700,whiteSpace:"nowrap"}}>{brl(v)}</td>
                      <td style={{...TD,whiteSpace:"nowrap"}}>
                        {sb>0
                          ?<span style={{fontWeight:800,color:"#dc2626"}}>{brl(sb)}</span>
                          :<span style={{color:"#16a34a",fontWeight:700}}>✓ Pago</span>
                        }
                      </td>
                      <td style={{...TD,fontWeight:700,color:l>=0?"#16a34a":"#dc2626",whiteSpace:"nowrap"}}>{brl(l)}</td>
                      <td style={TD}>{margemRecebida===null?<span style={{color:"#c4c1cc",fontSize:12}}>—</span>:<MargBadge marg={margemRecebida}/>}</td>
                      <td style={TD}><Badge status={isAtrasado(p)?"Atrasado":p.status}/></td>
                      <td style={TD}><div style={{display:"flex",gap:5}}>
                        <button onClick={()=>onEdit(p)} title="Editar" style={{width:30,height:30,borderRadius:7,border:"1px solid #e5e7eb",background:"#f9fafb",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:"#374151"}}>
                          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4z"/></svg>
                        </button>
                        <button onClick={()=>onDelete(p.id)} title="Excluir" style={{width:30,height:30,borderRadius:7,border:"1px solid #fecaca",background:"#fef2f2",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:"#dc2626"}}>
                          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg>
                        </button>
                      </div></td>
                    </HRow>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Section>

      {/* Seção colapsável de pedidos para estoque — Opção B */}
      {filtradosEstoque.length>0&&(
        <EstoqueColapsavel pedidos={filtradosEstoque} onEdit={onEdit} onDelete={onDelete}/>
      )}
      {mm&&<Modal title="Editar Meta Mensal" onClose={()=>setMm(false)}>
        <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
          <Field label="Meta de Pedidos"><Inp type="number" min="0" value={mt.pedidos} onChange={e=>setMt(m=>({...m,pedidos:parseInt(e.target.value)||0}))}/></Field>
          <Field label="Meta de Faturamento (R$)"><Inp type="number" min="0" step="0.01" value={mt.receita} onChange={e=>setMt(m=>({...m,receita:parseFloat(e.target.value)||0}))}/></Field>
          <Field label="Meta de Lucro (R$) — usada na Central"><Inp type="number" min="0" step="0.01" value={mt.lucro} onChange={e=>setMt(m=>({...m,lucro:parseFloat(e.target.value)||0}))}/></Field>
        </div>
        <MBtns onClose={()=>setMm(false)} onSave={()=>{onUpdateMeta(mt);setMm(false);}} label="Salvar Meta"/>
      </Modal>}
    </div>
  );
}

// ── GESTÃO KANBAN ─────────────────────────────────────────────
// ── CUSTO/LUCRO ───────────────────────────────────────────────
function PageCusto({db,setDb}){
  const [filtro,setFiltro]=useState("mes");const [modalD,setModalD]=useState(false);
  const [fd,setFd]=useState({data:hoje(),categoria:"Produto / Estoque",descricao:"",valor:0});
  const m=mesAtual();const hj=hoje();const sw=semIni();const mp=mesPrev();
  const FILTROS=[{k:"hoje",l:"Hoje"},{k:"semana",l:"Esta semana"},{k:"mes",l:"Este mês"},{k:"mes_ant",l:"Mês passado"},{k:"todos",l:"Todos"}];
  const fd2=x=>{const d=x.data||"";if(filtro==="hoje")return d===hj;if(filtro==="semana")return d>=sw;if(filtro==="mes_ant")return d.startsWith(mp);if(filtro==="todos")return true;return d.startsWith(m);};

  // Pedidos de venda (sem estoque) no período
  const peds=db.pedidos.filter(p=>fd2(p)&&!isEstoque(p));
  const recTotal=r(peds.reduce((a,p)=>a+(p.precoVenda||0)*(p.qtd||1),0));
  const recebido=r(peds.reduce((a,p)=>a+(p.valorRecebido||0),0));
  const aReceber=r(recTotal-recebido);
  const cusProd=r(peds.reduce((a,p)=>a+(p.custoProduto||0)*(p.qtd||1),0));
  const cusTaxa=r(peds.reduce((a,p)=>a+(p.custoTaxa||0)*(p.qtd||1),0));

  // Despesas manuais (Caixa - tipo Saída) no período
  const despesas=db.caixa.filter(c=>c.tipo==="Saída"&&fd2(c));
  const totDesp=r(despesas.reduce((a,c)=>a+(c.valor||0),0));

  const cusTotal=r(cusProd+cusTaxa+totDesp);
  const lucBruto=r(recTotal-cusProd-cusTaxa);
  const lucLiq=r(recTotal-cusTotal);
  const marg=recTotal>0?r((lucLiq/recTotal)*100):0;
  // Atual: baseado só no que já entrou de fato (recebido), não no faturamento projetado
  const lucLiqAtual=r(recebido-cusTotal);
  const margAtual=recebido>0?r((lucLiqAtual/recebido)*100):null;

  const salvD=()=>{
    if(!fd.descricao.trim())return alert("Informe a descrição.");
    if(!fd.valor||fd.valor<=0)return alert("Informe o valor.");
    setDb(prev=>{const id=prev.nextId+1;return{...prev,nextId:id,caixa:[...prev.caixa,{...fd,tipo:"Saída",id}]};});
    setFd({data:hoje(),categoria:"Produto / Estoque",descricao:"",valor:0});
    setModalD(false);
  };
  const delD=id=>{if(!window.confirm("Excluir?"))return;setDb(prev=>({...prev,caixa:prev.caixa.filter(c=>c.id!==id)}));};

  return(
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}>
        <div style={{fontSize:22,fontWeight:800,color:"#111"}}>Custo / Lucro</div>
        <Btn onClick={()=>setModalD(true)}>+ Despesa</Btn>
      </div>
      <div style={{marginBottom:16}}><Tabs options={FILTROS} value={filtro} onChange={setFiltro}/></div>

      {/* KPIs principais — margem real primeiro, é o que já entrou de fato */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(5,minmax(0,1fr))",gap:12,marginBottom:16}}>
        <KPI label="💰 Faturamento" value={brl(recTotal)} color="#111"/>
        <KPI label="✅ Recebido" value={brl(recebido)} color="#16a34a"/>
        <KPI label="⏳ A Receber" value={brl(aReceber)} color={aReceber>0?"#ca8a04":"#16a34a"}/>
        <KPI label="📈 Margem Real" value={margAtual===null?"—":`${margAtual.toFixed(1)}%`}
          color={margAtual===null?"#9ca3af":margAtual>=30?"#16a34a":margAtual>=15?"#ca8a04":"#dc2626"}/>
        <KPI label="📊 Margem Projetada" value={`${marg.toFixed(1)}%`} color={marg>=30?"#16a34a":marg>=15?"#ca8a04":"#dc2626"}/>
      </div>

      {/* Resumo financeiro */}
      <Section title="📋 Resumo do Período">
        {[
          {icon:"💰",label:"Receita Total (vendas)",value:brl(recTotal),color:"#111",bold:false},
          {icon:"📦",label:"Custo dos Produtos",value:`- ${brl(cusProd)}`,color:"#dc2626",bold:false},
          {icon:"📋",label:"Taxas / Importação",value:`- ${brl(cusTaxa)}`,color:"#dc2626",bold:false},
          {icon:"🏆",label:"Lucro Bruto",value:brl(lucBruto),color:lucBruto>=0?"#16a34a":"#dc2626",bold:true},
          {icon:"🧾",label:"Despesas (frete, outros)",value:`- ${brl(totDesp)}`,color:"#dc2626",bold:false},
        ].map(({icon,label,value,color,bold})=>(
          <div key={label} style={{display:"flex",justifyContent:"space-between",alignItems:"center",
            padding:"12px 0",borderBottom:"1px solid #f5f5f5"}}>
            <span style={{fontSize:14,color:"#374151",fontWeight:bold?700:400}}>{icon} {label}</span>
            <span style={{fontSize:bold?17:15,fontWeight:bold?800:600,color}}>{value}</span>
          </div>
        ))}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",
          padding:"14px 0",borderTop:"2px solid #e5e7eb",marginTop:4}}>
          <span style={{fontSize:15,fontWeight:800,color:"#111"}}>📈 Lucro Líquido Real</span>
          <span style={{fontSize:20,fontWeight:900,color:lucLiqAtual>=0?"#16a34a":"#dc2626"}}>{brl(lucLiqAtual)}</span>
        </div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 0"}}>
          <span style={{fontSize:13,fontWeight:700,color:"#6b7280"}}>🎯 Lucro Líquido Projetado</span>
          <span style={{fontSize:16,fontWeight:800,color:lucLiq>=0?"#16a34a":"#dc2626"}}>{brl(lucLiq)}</span>
        </div>
      </Section>

      {/* Pedidos no período */}
      <Section title={`🛒 Pedidos (${peds.length})`}>
        {peds.length===0?<Empty msg="Nenhum pedido de venda neste período." icon="🛒"/>:(
          <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead><tr>{["Data","Cliente","Camisa","Vendido","Recebido","Custo","Lucro","Margem","Status"].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
            <tbody>{[...peds].reverse().map(p=>{
              const v=r((p.precoVenda||0)*(p.qtd||1));
              const c=r(((p.custoProduto||0)+(p.custoTaxa||0))*(p.qtd||1));
              const l=r(v-c);const mg2=v>0?r((l/v)*100):0;
              return<HRow key={p.id}>
                <td style={{...TD,color:"#9ca3af"}}>{fmtData(p.data)}</td>
                <td style={{...TD,fontWeight:700}}>{p.cliente}</td>
                <td style={TD}>{p.time||p.camisa}{p.ano?` ${p.ano}`:""} {p.tamanho}</td>
                <td style={{...TD,fontWeight:700}}>{brl(v)}</td>
                <td style={{...TD,color:"#16a34a",fontWeight:700}}>{brl(p.valorRecebido||0)}</td>
                <td style={{...TD,color:"#dc2626"}}>{brl(c)}</td>
                <td style={{...TD,fontWeight:700,color:l>=0?"#16a34a":"#dc2626"}}>{brl(l)}</td>
                <td style={TD}><MargBadge marg={mg2}/></td>
                <td style={TD}><Badge status={p.status}/></td>
              </HRow>;
            })}</tbody>
          </table></div>
        )}
      </Section>

      {/* Despesas manuais */}
      <Section title="🧾 Despesas Manuais">
        {despesas.length===0?<Empty msg="Nenhuma despesa neste período." icon="🧾"/>:(
          <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead><tr>{["Data","Categoria","Descrição","Valor",""].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
            <tbody>{[...despesas].reverse().map(c=>(
              <HRow key={c.id}>
                <td style={{...TD,color:"#9ca3af"}}>{fmtData(c.data)}</td>
                <td style={TD}><span style={{background:"#f3f4f6",color:"#374151",padding:"2px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>{c.categoria}</span></td>
                <td style={{...TD,fontWeight:600,color:"#111"}}>{c.descricao}</td>
                <td style={{...TD,fontWeight:700,color:"#dc2626"}}>- {brl(c.valor)}</td>
                <td style={TD}><button onClick={()=>delD(c.id)} style={{width:32,height:32,borderRadius:7,border:"1px solid #fecaca",background:"#fef2f2",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",color:"#dc2626"}}><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg></button></td>
              </HRow>
            ))}</tbody>
          </table></div>
        )}
      </Section>

      {modalD&&<Modal title="Nova Despesa" onClose={()=>setModalD(false)}>
        <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
          <Field label="Data" half><Inp type="date" value={fd.data} onChange={e=>setFd(p=>({...p,data:e.target.value}))}/></Field>
          <Field label="Categoria" half><Sel value={fd.categoria} onChange={e=>setFd(p=>({...p,categoria:e.target.value}))}>{CATS_DESP.map(c=><option key={c}>{c}</option>)}</Sel></Field>
          <Field label="Descrição"><Inp value={fd.descricao} onChange={e=>setFd(p=>({...p,descricao:e.target.value}))} placeholder="ex: Frete 10 camisas Bahia..." autoFocus/></Field>
          <Field label="Valor (R$)"><Inp type="number" min="0" step="0.01" value={fd.valor} onChange={e=>setFd(p=>({...p,valor:parseFloat(e.target.value)||0}))}/></Field>
        </div>
        <MBtns onClose={()=>setModalD(false)} onSave={salvD}/>
      </Modal>}
    </div>
  );
}

// ── CAIXA ────────────────────────────────────────────────────
function PageCaixa({db,setDb}){
  const [filtro,setFiltro]=useState("mes");
  const [modalTipo,setModalTipo]=useState(null); // "Entrada" ou "Saída"
  const [f,setF]=useState({data:hoje(),tipo:"Entrada",descricao:"",valor:0,categoria:"Venda"});
  const m=mesAtual();const hj=hoje();const sw=semIni();const mp=mesPrev();
  const FILTROS=[{k:"hoje",l:"Hoje"},{k:"semana",l:"Esta semana"},{k:"mes",l:"Este mês"},{k:"mes_ant",l:"Mês passado"},{k:"todos",l:"Todos"}];
  const fd2=x=>{const d=x.data||"";if(filtro==="hoje")return d===hj;if(filtro==="semana")return d>=sw;if(filtro==="mes_ant")return d.startsWith(mp);if(filtro==="todos")return true;return d.startsWith(m);};

  // ✅ Entradas automáticas: valor recebido dos pedidos de venda no período
  const pedsRecebidos=db.pedidos.filter(p=>fd2(p)&&!isEstoque(p)&&(p.valorRecebido||0)>0);
  const entAutomatic=r(pedsRecebidos.reduce((a,p)=>a+(p.valorRecebido||0),0));

  // Entradas manuais (ex: venda extra, reembolso)
  const entManual=db.caixa.filter(c=>c.tipo==="Entrada"&&fd2(c));
  const totEntManual=r(entManual.reduce((a,c)=>a+(c.valor||0),0));

  // Saídas (despesas: frete, taxa, etc.)
  const saidas=db.caixa.filter(c=>c.tipo==="Saída"&&fd2(c));
  const totSaidas=r(saidas.reduce((a,c)=>a+(c.valor||0),0));

  const totalEntradas=r(entAutomatic+totEntManual);
  const saldo=r(totalEntradas-totSaidas);

  const abrirModal=(tipo)=>{
    setF({data:hoje(),tipo,descricao:"",valor:0,
      categoria:tipo==="Entrada"?"Venda extra":"Produto / Estoque"});
    setModalTipo(tipo);
  };

  const salv=()=>{
    if(!f.descricao.trim())return alert("Informe a descrição.");
    if(!f.valor||f.valor<=0)return alert("Informe o valor.");
    setDb(prev=>{const id=prev.nextId+1;return{...prev,nextId:id,caixa:[...prev.caixa,{...f,id}]};});
    setModalTipo(null);
  };
  const del=id=>{if(!window.confirm("Excluir?"))return;setDb(prev=>({...prev,caixa:prev.caixa.filter(c=>c.id!==id)}));};

  return(
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
        <div style={{fontSize:22,fontWeight:800,color:"#111"}}>Caixa</div>
        <div style={{display:"flex",gap:8}}>
          <button onClick={()=>abrirModal("Entrada")} style={{display:"flex",alignItems:"center",
            gap:7,padding:"9px 16px",borderRadius:9,border:"2px solid #16a34a",background:"#f0fdf4",
            color:"#16a34a",fontWeight:700,fontSize:13,cursor:"pointer"}}>
            💵 + Entrada
          </button>
          <button onClick={()=>abrirModal("Saída")} style={{display:"flex",alignItems:"center",
            gap:7,padding:"9px 16px",borderRadius:9,border:"2px solid #dc2626",background:"#fef2f2",
            color:"#dc2626",fontWeight:700,fontSize:13,cursor:"pointer"}}>
            🧾 + Despesa
          </button>
        </div>
      </div>
      <div style={{marginBottom:16}}><Tabs options={FILTROS} value={filtro} onChange={setFiltro}/></div>

      {/* Aviso explicativo */}
      <Alert type="info">
        💡 As <strong>entradas de vendas</strong> entram automaticamente quando você preenche o <strong>Valor Recebido</strong> em um pedido. Use <strong>+ Entrada</strong> só para recebimentos extras (reembolso, outros). Use <strong>+ Despesa</strong> para taxas, fretes e custos avulsos.
      </Alert>

      {/* KPIs */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,minmax(0,1fr))",gap:14,marginBottom:16}}>
        <HCard color="#16a34a">
          <div style={{fontSize:11,color:"#9ca3af",fontWeight:700,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:6}}>💵 ENTRADAS</div>
          <div style={{fontSize:22,fontWeight:800,color:"#16a34a"}}>{brl(totalEntradas)}</div>
          <div style={{fontSize:11,color:"#9ca3af",marginTop:4}}>
            Vendas: {brl(entAutomatic)}{totEntManual>0?` · Extra: ${brl(totEntManual)}`:""}
          </div>
        </HCard>
        <HCard color="#dc2626">
          <div style={{fontSize:11,color:"#9ca3af",fontWeight:700,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:6}}>🧾 SAÍDAS / DESPESAS</div>
          <div style={{fontSize:22,fontWeight:800,color:"#dc2626"}}>{brl(totSaidas)}</div>
          <div style={{fontSize:11,color:"#9ca3af",marginTop:4}}>Taxas, fretes e outros custos</div>
        </HCard>
        <HCard color={saldo>=0?"#16a34a":"#dc2626"}>
          <div style={{fontSize:11,color:"#9ca3af",fontWeight:700,textTransform:"uppercase",letterSpacing:"0.5px",marginBottom:6}}>🏦 SALDO DO PERÍODO</div>
          <div style={{fontSize:22,fontWeight:800,color:saldo>=0?"#16a34a":"#dc2626"}}>{brl(saldo)}</div>
          <div style={{fontSize:11,color:"#9ca3af",marginTop:4}}>Entradas – Despesas</div>
        </HCard>
      </div>

      {/* Recebimentos automáticos das vendas */}
      <Section title="✅ Recebimentos de Vendas (automático)">
        {pedsRecebidos.length===0
          ?<Empty msg="Nenhum recebimento de venda neste período. Marque 'Valor Recebido' nos pedidos." icon="💵"/>
          :<div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead><tr>{["Data","Cliente","Camisa","Valor Recebido"].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
            <tbody>{[...pedsRecebidos].reverse().map(p=>(
              <HRow key={p.id}>
                <td style={{...TD,color:"#9ca3af"}}>{fmtData(p.data)}</td>
                <td style={{...TD,fontWeight:700}}>{p.cliente}</td>
                <td style={TD}>{p.time||p.camisa}{p.ano?` ${p.ano}`:""} {p.tamanho}</td>
                <td style={{...TD,fontWeight:800,color:"#16a34a",fontSize:15}}>+ {brl(p.valorRecebido||0)}</td>
              </HRow>
            ))}</tbody>
          </table></div>
        }
      </Section>

      {/* Despesas e entradas extras manuais */}
      <Section title="📒 Lançamentos Manuais">
        {(entManual.length+saidas.length)===0
          ?<Empty msg="Nenhum lançamento manual neste período." icon="📒"/>
          :<div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead><tr>{["Data","Descrição","Categoria","Valor",""].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
            <tbody>{[...db.caixa.filter(c=>fd2(c))].reverse().map(c=>(
              <HRow key={c.id}>
                <td style={{...TD,color:"#9ca3af"}}>{fmtData(c.data)}</td>
                <td style={{...TD,fontWeight:600,color:"#111"}}>{c.descricao}</td>
                <td style={TD}>
                  <span style={{background:c.tipo==="Entrada"?"#f0fdf4":"#fef2f2",
                    color:c.tipo==="Entrada"?"#16a34a":"#dc2626",
                    border:`1px solid ${c.tipo==="Entrada"?"#bbf7d0":"#fecaca"}`,
                    padding:"2px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>
                    {c.categoria||c.tipo}
                  </span>
                </td>
                <td style={{...TD,fontWeight:700,color:c.tipo==="Entrada"?"#16a34a":"#dc2626"}}>
                  {c.tipo==="Entrada"?"+ ":"- "}{brl(c.valor)}
                </td>
                <td style={TD}>
                  <button onClick={()=>del(c.id)} style={{width:32,height:32,borderRadius:7,
                    border:"1px solid #fecaca",background:"#fef2f2",cursor:"pointer",
                    display:"flex",alignItems:"center",justifyContent:"center",color:"#dc2626"}}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4h6v2"/></svg>
                  </button>
                </td>
              </HRow>
            ))}</tbody>
          </table></div>
        }
      </Section>

      {modalTipo&&(
        <Modal title={modalTipo==="Entrada"?"💵 Nova Entrada Extra":"🧾 Nova Despesa"} onClose={()=>setModalTipo(null)}>
          <Alert type={modalTipo==="Entrada"?"success":"error"}>
            {modalTipo==="Entrada"
              ?"Use para recebimentos que não são vendas cadastradas (ex: reembolso, venda avulsa)."
              :"Registre aqui custos como frete, taxa, embalagem, ferramentas, etc."}
          </Alert>
          <div style={{display:"flex",flexWrap:"wrap",gap:12,marginTop:12}}>
            <Field label="Data" half><Inp type="date" value={f.data} onChange={e=>setF(p=>({...p,data:e.target.value}))}/></Field>
            <Field label="Categoria" half>
              <Sel value={f.categoria} onChange={e=>setF(p=>({...p,categoria:e.target.value}))}>
                {(modalTipo==="Entrada"?CATS_REC:CATS_DESP).map(c=><option key={c}>{c}</option>)}
              </Sel>
            </Field>
            <Field label="Descrição"><Inp value={f.descricao} onChange={e=>setF(p=>({...p,descricao:e.target.value}))} placeholder={modalTipo==="Entrada"?"ex: Reembolso, venda extra...":"ex: Frete 4 camisas Vitória..."} autoFocus/></Field>
            <Field label="Valor (R$)"><Inp type="number" min="0" step="0.01" value={f.valor} onChange={e=>setF(p=>({...p,valor:parseFloat(e.target.value)||0}))}/></Field>
          </div>
          <MBtns onClose={()=>setModalTipo(null)} onSave={salv}
            label={modalTipo==="Entrada"?"Registrar Entrada":"Registrar Despesa"}/>
        </Modal>
      )}
    </div>
  );
}

// ── TAREFAS ──────────────────────────────────────────────────
// ── WORK (antiga "Tarefas") — centro operacional da empresa ────

// Card compacto da lista de Execução — 2 linhas, sem inchaço visual.
// ── DIAGRAMA DO OBJETIVO — nós conectados, um passo de cada vez ────
function NoEtapa({etapa,index,estado,onToggle,onEditar,onRemover,onSubir,onDescer,ultimo}){
  // estado: "feita" | "atual" | "futura"
  const [editando,setEditando]=useState(false);
  const [titulo,setTitulo]=useState(etapa.titulo);
  const [porque,setPorque]=useState(etapa.porque);
  const [h,setH]=useState(false);
  const cores={feita:{bola:"#16a34a",texto:"#9ca3af",linha:"#16a34a"},
    atual:{bola:"#5c2030",texto:"#111",linha:"#d1d5db"},
    futura:{bola:"#fff",texto:"#9ca3af",linha:"#d1d5db"}};
  const c=cores[estado];
  const salvar=()=>{onEditar(etapa.id,{titulo:titulo.trim()||etapa.titulo,porque:porque.trim()});setEditando(false);};
  return(
    <div style={{display:"flex",gap:12}} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}>
      <div style={{display:"flex",flexDirection:"column",alignItems:"center",flexShrink:0}}>
        <button onClick={()=>onToggle(etapa.id)} title={estado==="feita"?"Desmarcar":"Marcar como concluída"}
          style={{width:estado==="atual"?30:26,height:estado==="atual"?30:26,borderRadius:"50%",
            background:estado==="futura"?"#fff":c.bola,border:`2px solid ${c.bola}`,color:estado==="futura"?"#d1d5db":"#fff",
            display:"flex",alignItems:"center",justifyContent:"center",fontSize:estado==="atual"?13:12,
            fontWeight:700,cursor:"pointer",flexShrink:0,
            boxShadow:estado==="atual"?"0 0 0 4px #5c203022":"none",transition:"all 0.15s"}}>
          {estado==="feita"?"✓":index+1}
        </button>
        {!ultimo&&<div style={{width:2,flex:1,minHeight:26,
          background:estado==="feita"?c.linha:"repeating-linear-gradient(to bottom,#d1d5db 0 4px,transparent 4px 8px)"}}/>}
      </div>
      <div style={{flex:1,paddingBottom:18,minWidth:0}}>
        {editando?(
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
            <input value={titulo} onChange={e=>setTitulo(e.target.value)} autoFocus
              style={{...INP,fontWeight:700,fontSize:13.5}} placeholder="Título da etapa"/>
            <input value={porque} onChange={e=>setPorque(e.target.value)}
              style={{...INP,fontSize:12}} placeholder="Por quê? (o que essa etapa destrava)"/>
            <div style={{display:"flex",gap:6}}>
              <Btn onClick={salvar}>Salvar</Btn>
              <Btn v="danger" onClick={()=>setEditando(false)}>Cancelar</Btn>
            </div>
          </div>
        ):(
          <div onClick={()=>setEditando(true)} style={{cursor:"pointer"}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <span style={{fontWeight:estado==="atual"?800:600,fontSize:estado==="atual"?14:13.5,
                color:c.texto,textDecoration:estado==="feita"?"line-through":"none"}}>{etapa.titulo}</span>
              {estado==="atual"&&<span style={{fontSize:10,fontWeight:700,color:"#5c2030",
                background:"#faf5f6",borderRadius:10,padding:"1px 8px",flexShrink:0}}>ETAPA ATUAL</span>}
            </div>
            {etapa.porque&&<div style={{fontSize:11.5,color:estado==="futura"?"#d1d5db":"#9ca3af",marginTop:2}}>{etapa.porque}</div>}
            {h&&(
              <div style={{display:"flex",gap:10,marginTop:6}}>
                <button onClick={e=>{e.stopPropagation();onSubir(etapa.id);}} style={{background:"none",border:"none",
                  color:"#9ca3af",fontSize:11,cursor:"pointer",padding:0}}>↑ subir</button>
                <button onClick={e=>{e.stopPropagation();onDescer(etapa.id);}} style={{background:"none",border:"none",
                  color:"#9ca3af",fontSize:11,cursor:"pointer",padding:0}}>↓ descer</button>
                <button onClick={e=>{e.stopPropagation();onRemover(etapa.id);}} style={{background:"none",border:"none",
                  color:"#dc2626",fontSize:11,cursor:"pointer",padding:0}}>remover</button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function DiagramaObjetivo({etapas,onMudar}){
  const [novaEtapa,setNovaEtapa]=useState("");
  const idx=etapas.findIndex(e=>!e.concluida);

  const toggle=id=>{
    const i=etapas.findIndex(e=>e.id===id);
    onMudar(etapas.map((e,j)=>j===i?{...e,concluida:!e.concluida}:e));
  };
  const editar=(id,patch)=>onMudar(etapas.map(e=>e.id===id?{...e,...patch}:e));
  const remover=id=>onMudar(etapas.filter(e=>e.id!==id));
  const mover=(id,dir)=>{
    const i=etapas.findIndex(e=>e.id===id);
    const j=i+dir;
    if(j<0||j>=etapas.length)return;
    const nova=[...etapas];
    [nova[i],nova[j]]=[nova[j],nova[i]];
    onMudar(nova);
  };
  const adicionar=()=>{
    if(!novaEtapa.trim())return;
    const proxId=(etapas.reduce((m,e)=>Math.max(m,e.id),0)||0)+1;
    onMudar([...etapas,{id:proxId,titulo:novaEtapa.trim(),porque:"",concluida:false}]);
    setNovaEtapa("");
  };

  return(
    <div>
      {etapas.length>0&&(
        <div style={{marginBottom:10}}>
          {etapas.map((e,i)=>(
            <NoEtapa key={e.id} etapa={e} index={i} ultimo={i===etapas.length-1}
              estado={e.concluida?"feita":i===idx?"atual":"futura"}
              onToggle={toggle} onEditar={editar} onRemover={remover} onSubir={id=>mover(id,-1)} onDescer={id=>mover(id,1)}/>
          ))}
        </div>
      )}
      <div style={{display:"flex",gap:8}}>
        <input value={novaEtapa} onChange={e=>setNovaEtapa(e.target.value)}
          onKeyDown={e=>{if(e.key==="Enter")adicionar();}}
          placeholder="+ nova etapa" style={{...INP,fontSize:12.5,padding:"7px 10px"}}/>
        <Btn onClick={adicionar}>Add</Btn>
      </div>
    </div>
  );
}

function CardExecucao({t,onToggle,onStatus,onDelete,onEdit,onFavoritar}){
  const [h,setH]=useState(false);
  const atrasada=t.status!=="Concluído"&&t.status!=="Cancelado"&&t.prazo&&t.prazo<hoje();
  const feita=t.status==="Concluído";
  return(
    <div onClick={()=>onEdit(t)} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
      style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",cursor:"pointer",
        border:`1px solid ${h?"#d1d5db":"#eef0f2"}`,
        borderLeft:`3px solid ${feita?"#d1d5db":COR_URGENCIA_WORK[t.urgencia]||"#111"}`,
        borderRadius:8,background:"#fff",opacity:t.status==="Cancelado"?0.55:1,transition:"all 0.12s"}}>
      <button onClick={e=>{e.stopPropagation();onToggle(t);}} style={{width:19,height:19,borderRadius:6,
        border:`2px solid ${feita?"#16a34a":"#d1d5db"}`,background:feita?"#16a34a":"none",
        cursor:"pointer",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",
        color:"#fff",fontSize:11}}>{feita?"✓":""}</button>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:13.5,fontWeight:600,color:"#111",textAlign:"left",whiteSpace:"nowrap",
          overflow:"hidden",textOverflow:"ellipsis",textDecoration:feita?"line-through":"none"}}>
          {t.favorito?"⭐ ":""}{ICONE_AREA_WORK[t.categoria]} {t.titulo}
        </div>
        <div style={{fontSize:11.5,color:atrasada?"#dc2626":"#9ca3af",fontWeight:atrasada?700:400,
          marginTop:2,textAlign:"left"}}>
          {t.categoria} · {t.urgencia} · {t.prazo?fmtData(t.prazo):"sem data"}{atrasada?" · atrasada":""}
          {t.etapas&&t.etapas.length>0&&` · 🗺️ ${progressoEtapas(t.etapas).feitas}/${progressoEtapas(t.etapas).total}`}
        </div>
      </div>
      <div onClick={e=>e.stopPropagation()} style={{display:"flex",alignItems:"center",gap:6,flexShrink:0}}>
        <select value={t.status} onChange={e=>onStatus(t,e.target.value)}
          style={{fontSize:10.5,fontWeight:700,color:COR_STATUS_WORK[t.status],background:"#f9fafb",
            border:`1px solid ${COR_STATUS_WORK[t.status]}55`,borderRadius:20,padding:"3px 7px",cursor:"pointer"}}>
          {STATUS_WORK.map(s=><option key={s} value={s}>{s}</option>)}
        </select>
        <button onClick={()=>onFavoritar(t)} title="Favoritar" style={{background:"none",border:"none",
          cursor:"pointer",fontSize:14,color:t.favorito?"#d4af37":"#d1d5db",padding:"0 2px"}}>
          {t.favorito?"★":"☆"}
        </button>
        <button onClick={()=>onDelete(t.id)} title="Excluir" style={{background:"none",border:"none",
          cursor:"pointer",fontSize:13,color:"#d1d5db",padding:"0 2px"}}>✕</button>
      </div>
    </div>
  );
}

function PageTarefas({db,setDb}){
  const [modal,setModal]=useState(null); // null=fechado, "novo"=criando, {...tarefa}=editando
  const [filtroPrincipal,setFiltroPrincipal]=useState("todas");
  const [catFiltro,setCatFiltro]=useState("Todas");
  const [prioFiltro,setPrioFiltro]=useState("Todas");
  const [dataFiltro,setDataFiltro]=useState(null);
  const [busca,setBusca]=useState("");
  const vazio={titulo:"",descricao:"",objetivo:"",categoria:"Operacional",urgencia:"Média",prazo:"",
    status:"Pendente",responsavel:"",recorrencia:"Nenhuma",recorrenciaDias:7,projetoRelacionado:"",
    mostrarNaCentral:false,favorito:false,proximaAcao:"",observacoes:"",historico:[],etapas:[]};
  const [f,setF]=useState(vazio);
  const hj=hoje();

  const abertas=db.tarefas.filter(t=>t.status!=="Concluído"&&t.status!=="Cancelado");
  const urgentesCount=abertas.filter(t=>t.urgencia==="Crítica"||t.urgencia==="Alta").length;
  const atrasadasCount=abertas.filter(t=>t.prazo&&t.prazo<hj).length;
  const andamentoCount=db.tarefas.filter(t=>t.status==="Em Andamento").length;
  const concluidasCount=db.tarefas.filter(t=>t.status==="Concluído").length;
  const hojeCount=abertas.filter(t=>t.prazo===hj).length;
  const semana=diasDaSemanaAtual();
  const semanaCount=abertas.filter(t=>t.prazo&&t.prazo>=semana[0].data&&t.prazo<=semana[6].data).length;

  const foco=ordenarTarefasPorPrioridade(db.tarefas.filter(tarefaMereceAtencao)).slice(0,3);
  const proximasAcoes=ordenarTarefasPorPrioridade(abertas.filter(t=>t.prazo&&t.prazo>=hj)).slice(0,6);
  const backlog=abertas.filter(t=>!t.prazo);

  const INDICADORES=[
    {k:"urgentes",icon:"🔴",label:"Urgentes",valor:urgentesCount},
    {k:"atrasadas",icon:"⚠️",label:"Atrasadas",valor:atrasadasCount},
    {k:"andamento",icon:"🔵",label:"Em andamento",valor:andamentoCount},
    {k:"concluidas",icon:"🟢",label:"Concluídas",valor:concluidasCount},
    {k:"hoje",icon:"📅",label:"Hoje",valor:hojeCount},
    {k:"semana",icon:"📌",label:"Esta semana",valor:semanaCount},
  ];

  const execucao=ordenarTarefasPorPrioridade(db.tarefas.filter(t=>{
    if(catFiltro!=="Todas"&&t.categoria!==catFiltro)return false;
    if(prioFiltro!=="Todas"&&t.urgencia!==prioFiltro)return false;
    if(dataFiltro&&t.prazo!==dataFiltro)return false;
    if(busca.trim()){
      const q=busca.trim().toLowerCase();
      if(!(t.titulo||"").toLowerCase().includes(q)&&!(t.descricao||"").toLowerCase().includes(q))return false;
    }
    switch(filtroPrincipal){
      case"hoje":return t.prazo===hj&&t.status!=="Concluído"&&t.status!=="Cancelado";
      case"atrasadas":return t.prazo&&t.prazo<hj&&t.status!=="Concluído"&&t.status!=="Cancelado";
      case"urgentes":return(t.urgencia==="Crítica"||t.urgencia==="Alta")&&t.status!=="Concluído"&&t.status!=="Cancelado";
      case"andamento":return t.status==="Em Andamento";
      case"concluidas":return t.status==="Concluído";
      default:return true;
    }
  }));

  const ABAS_EXECUCAO=[{k:"todas",l:"Todas"},{k:"hoje",l:"Hoje"},{k:"atrasadas",l:"Atrasadas"},
    {k:"urgentes",l:"Urgentes"},{k:"andamento",l:"Em andamento"},{k:"concluidas",l:"Concluídas"}];

  const abrirNova=()=>{setF(vazio);setModal("novo");};
  const abrirEdicao=t=>{setF({...vazio,...t});setModal(t);};
  const salv=()=>{
    if(!f.titulo.trim())return alert("Informe o título.");
    if(modal&&modal!=="novo"){
      setDb(prev=>({...prev,tarefas:prev.tarefas.map(t=>t.id===f.id?
        {...f,historico:registrarHistorico(f,"Atividade editada")}:t)}));
    } else {
      setDb(prev=>{const id=prev.nextId+1;return{...prev,nextId:id,
        tarefas:[...prev.tarefas,{...f,id,criadoEm:hoje(),historico:[{data:hoje(),texto:"Atividade criada"}]}]};});
    }
    setF(vazio);setModal(null);
  };
  // Concluir com consciência de recorrência: gera a próxima ocorrência automática.
  const concluir=t=>setDb(prev=>{
    let tarefas=prev.tarefas.map(x=>x.id===t.id?
      {...x,status:"Concluído",historico:registrarHistorico(x,"Marcada como concluída")}:x);
    let nextId=prev.nextId;
    if(t.recorrencia&&t.recorrencia!=="Nenhuma"){
      const prox=proximaOcorrencia(t.prazo,t.recorrencia,t.recorrenciaDias);
      nextId=nextId+1;
      tarefas=[...tarefas,{...t,id:nextId,status:"Pendente",prazo:prox,
        historico:[{data:hoje(),texto:"Gerada automaticamente pela recorrência"}]}];
    }
    return{...prev,tarefas,nextId};
  });
  const toggle=t=>{
    if(t.status==="Concluído"){
      setDb(prev=>({...prev,tarefas:prev.tarefas.map(x=>x.id===t.id?
        {...x,status:"Pendente",historico:registrarHistorico(x,"Reaberta")}:x)}));
    } else concluir(t);
  };
  const mudarStatus=(t,status)=>{
    if(status==="Concluído")concluir(t);
    else setDb(prev=>({...prev,tarefas:prev.tarefas.map(x=>x.id===t.id?
      {...x,status,historico:registrarHistorico(x,`Status alterado para "${status}"`)}:x)}));
  };
  const favoritar=t=>setDb(prev=>({...prev,tarefas:prev.tarefas.map(x=>
    x.id===t.id?{...x,favorito:!x.favorito}:x)}));
  const del=id=>{if(!window.confirm("Excluir?"))return;setDb(prev=>({...prev,tarefas:prev.tarefas.filter(t=>t.id!==id)}));};
  const salvarMissao=v=>setDb(prev=>({...prev,centralComando:{...prev.centralComando,missao:v}}));
  const atualizar=()=>setDb(prev=>({...prev}));

  return(
    <div>
      {/* Header */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div>
          <div style={{fontSize:20,fontWeight:800,color:"#111",letterSpacing:"0.3px"}}>WORK</div>
          <div style={{fontSize:12.5,color:"#9ca3af"}}>Centro operacional da T11</div>
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <Inp value={busca} onChange={e=>setBusca(e.target.value)} placeholder="Buscar atividade..." style={{width:180}}/>
          <button onClick={atualizar} title="Atualizar" style={{background:"#fff",border:"1px solid #e5e7eb",
            borderRadius:8,padding:"8px 10px",cursor:"pointer",fontSize:13,color:"#6b7280"}}>🔄</button>
          <Btn onClick={abrirNova}>+ Nova atividade</Btn>
        </div>
      </div>

      {/* Foco de Hoje */}
      <div style={{background:"#1D1A28",borderRadius:12,padding:"16px 20px",marginBottom:14}}>
        <div style={{fontSize:11,color:"#a8a5b3",textTransform:"uppercase",letterSpacing:"0.5px",
          fontWeight:700,marginBottom:10}}>🎯 Foco de hoje</div>
        {foco.length===0?(
          <div>
            <div style={{fontSize:13.5,color:"#5cd680",marginBottom:10}}>✓ Nada crítico ou urgente agora.</div>
            <div style={{fontSize:10.5,color:"#a8a5b3",marginBottom:4,textTransform:"uppercase"}}>
              Objetivo do dia (aparece na Central se nada mais urgente surgir)
            </div>
            <CampoEditavel valor={db.centralComando.missao} placeholder="Qual sua prioridade hoje?"
              onSalvar={salvarMissao}/>
          </div>
        ):(
          <div style={{display:"flex",flexDirection:"column",gap:8}}>
            {foco.map(t=>{
              const atrasada=t.prazo&&t.prazo<hj;
              return(
                <div key={t.id} style={{display:"flex",alignItems:"center",gap:10,background:"#262233",
                  borderRadius:9,padding:"10px 12px"}}>
                  <span style={{width:7,height:7,borderRadius:"50%",flexShrink:0,background:COR_URGENCIA_WORK[t.urgencia]}}/>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontSize:14,fontWeight:700,color:"#fff"}}>{t.titulo}</div>
                    <div style={{fontSize:11.5,color:"#a8a5b3",marginTop:2}}>
                      {t.urgencia==="Crítica"?"🔴":"🟠"} {t.urgencia} · {atrasada?"atrasada":t.prazo===hj?"hoje":fmtData(t.prazo)} · 📍 {t.categoria}
                    </div>
                  </div>
                  <button onClick={()=>concluir(t)} style={{background:"#274d3a",color:"#7ee0a8",border:"none",
                    borderRadius:6,padding:"5px 11px",fontSize:11.5,fontWeight:700,cursor:"pointer",flexShrink:0}}>
                    ✓ Concluir
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Resumo operacional — clicável, filtra a Execução */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(6,minmax(0,1fr))",gap:8,marginBottom:14}}>
        {INDICADORES.map(ind=>(
          <div key={ind.k} onClick={()=>setFiltroPrincipal(filtroPrincipal===ind.k?"todas":ind.k)}
            style={{background:"#fff",border:`1px solid ${filtroPrincipal===ind.k?"#5c2030":"#e5e7eb"}`,
              borderRadius:9,padding:"9px 10px",cursor:"pointer",transition:"all 0.12s"}}>
            <div style={{fontSize:11,color:"#9ca3af"}}>{ind.icon} {ind.label}</div>
            <div style={{fontSize:18,fontWeight:800,color:"#111",marginTop:2}}>{ind.valor}</div>
          </div>
        ))}
      </div>

      {/* Áreas — navegação compacta, não cards grandes */}
      <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:14}}>
        {CATEGORIAS_WORK.map(area=>{
          const n=abertas.filter(t=>t.categoria===area).length;
          const ativo=catFiltro===area;
          return(
            <button key={area} onClick={()=>setCatFiltro(ativo?"Todas":area)}
              style={{background:ativo?"#5c2030":"#fff",color:ativo?"#fff":"#374151",
                border:`1px solid ${ativo?"#5c2030":"#e5e7eb"}`,borderRadius:20,padding:"6px 13px",
                fontSize:12.5,fontWeight:600,cursor:"pointer",display:"flex",alignItems:"center",gap:5}}>
              {ICONE_AREA_WORK[area]} {area} <span style={{opacity:0.7}}>· {n}</span>
            </button>
          );
        })}
      </div>

      {/* Semana — visão operacional rápida, sem calendário gigante */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(7,minmax(0,1fr))",gap:6,marginBottom:16}}>
        {semana.map(dia=>{
          const n=abertas.filter(t=>t.prazo===dia.data).length;
          const ativo=dataFiltro===dia.data;
          const ehHoje=dia.data===hj;
          return(
            <button key={dia.data} onClick={()=>setDataFiltro(ativo?null:dia.data)}
              style={{background:ativo?"#5c2030":"#fff",border:`1px solid ${ehHoje&&!ativo?"#d4af37":ativo?"#5c2030":"#e5e7eb"}`,
                borderRadius:9,padding:"8px 4px",cursor:"pointer",textAlign:"center"}}>
              <div style={{fontSize:10,fontWeight:700,color:ativo?"#fff":"#9ca3af"}}>{dia.label}</div>
              <div style={{fontSize:16,fontWeight:800,color:ativo?"#fff":n>0?"#111":"#d1d5db",marginTop:2}}>{n}</div>
            </button>
          );
        })}
      </div>

      {/* Execução + coluna lateral */}
      <div style={{display:"grid",gridTemplateColumns:"1.7fr 1fr",gap:16,alignItems:"start"}}>
        <Section title="EXECUÇÃO" action={
          <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
            <div style={{width:130}}>
              <Sel value={prioFiltro} onChange={e=>setPrioFiltro(e.target.value)}>
                <option value="Todas">Prioridade</option>
                {URGENCIAS_WORK.map(u=><option key={u} value={u}>{u}</option>)}
              </Sel>
            </div>
            <Tabs options={ABAS_EXECUCAO} value={filtroPrincipal} onChange={setFiltroPrincipal}/>
          </div>
        }>
          {execucao.length===0?<Empty msg="Nenhuma atividade encontrada com esses filtros." icon="💻"/>:(
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              {execucao.map(t=><CardExecucao key={t.id} t={t} onToggle={toggle} onStatus={mudarStatus}
                onDelete={del} onEdit={abrirEdicao} onFavoritar={favoritar}/>)}
            </div>
          )}
        </Section>

        <div style={{display:"flex",flexDirection:"column",gap:14}}>
          <Section title="🚀 Próximas Ações">
            {proximasAcoes.length===0?<div style={{fontSize:13,color:"#9ca3af"}}>Nada agendado por enquanto.</div>:(
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {proximasAcoes.map(t=>(
                  <div key={t.id} onClick={()=>abrirEdicao(t)} style={{cursor:"pointer"}}>
                    <div style={{fontSize:10.5,color:"#9ca3af",textTransform:"uppercase",fontWeight:700}}>{rotuloDia(t.prazo)}</div>
                    <div style={{fontSize:13,color:"#111",fontWeight:600}}>{t.titulo}</div>
                  </div>
                ))}
              </div>
            )}
          </Section>

          <Section title="🗂 Backlog">
            {backlog.length===0?<div style={{fontSize:13,color:"#9ca3af"}}>Sem ideias em espera.</div>:(
              <div style={{display:"flex",flexDirection:"column",gap:6}}>
                {backlog.map(t=>(
                  <div key={t.id} onClick={()=>abrirEdicao(t)} style={{fontSize:12.5,color:"#374151",
                    cursor:"pointer",padding:"4px 0"}}>{ICONE_AREA_WORK[t.categoria]} {t.titulo}</div>
                ))}
              </div>
            )}
          </Section>
        </div>
      </div>

      {modal&&<Modal title={modal==="novo"?"Nova Atividade":"Detalhes da Atividade"} onClose={()=>setModal(null)} wide>
        <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
          <Field label="O que precisa ser feito?"><Inp value={f.titulo} onChange={e=>setF(p=>({...p,titulo:e.target.value}))}
            placeholder="Título" autoFocus/></Field>
          <Field label="Por quê? (objetivo)"><Inp value={f.objetivo} onChange={e=>setF(p=>({...p,objetivo:e.target.value}))}
            placeholder="Por que essa atividade importa?"/></Field>
          <Field label="Descrição"><Inp value={f.descricao} onChange={e=>setF(p=>({...p,descricao:e.target.value}))}
            placeholder="Detalhes (opcional)"/></Field>
          <Field label="Área" third><Sel value={f.categoria} onChange={e=>setF(p=>({...p,categoria:e.target.value}))}>
            {CATEGORIAS_WORK.map(c=><option key={c}>{c}</option>)}</Sel></Field>
          <Field label="Prioridade" third><Sel value={f.urgencia} onChange={e=>setF(p=>({...p,urgencia:e.target.value}))}>
            {URGENCIAS_WORK.map(u=><option key={u}>{u}</option>)}</Sel></Field>
          <Field label="Status" third><Sel value={f.status} onChange={e=>setF(p=>({...p,status:e.target.value}))}>
            {STATUS_WORK.map(s=><option key={s}>{s}</option>)}</Sel></Field>
          <Field label="Prazo" third><Inp type="date" value={f.prazo} onChange={e=>setF(p=>({...p,prazo:e.target.value}))}/></Field>
          <Field label="Projeto relacionado" third><Inp value={f.projetoRelacionado}
            onChange={e=>setF(p=>({...p,projetoRelacionado:e.target.value}))} placeholder="Opcional"/></Field>
          <Field label="Mostrar na Central?" third><Sel value={f.mostrarNaCentral?"Sim":"Não"}
            onChange={e=>setF(p=>({...p,mostrarNaCentral:e.target.value==="Sim"}))}>
            <option>Não</option><option>Sim</option></Sel></Field>
          <Field label="Recorrência" third><Sel value={f.recorrencia} onChange={e=>setF(p=>({...p,recorrencia:e.target.value}))}>
            {RECORRENCIAS_WORK.map(r=><option key={r}>{r}</option>)}</Sel></Field>
          {f.recorrencia==="Personalizada"&&
            <Field label="A cada quantos dias" third><Inp type="number" min="1" value={f.recorrenciaDias}
              onChange={e=>setF(p=>({...p,recorrenciaDias:Number(e.target.value)||1}))}/></Field>}
          <Field label="Próxima ação"><Inp value={f.proximaAcao} onChange={e=>setF(p=>({...p,proximaAcao:e.target.value}))}
            placeholder="Qual o próximo passo concreto?"/></Field>
          <Field label="Observações"><Inp value={f.observacoes} onChange={e=>setF(p=>({...p,observacoes:e.target.value}))}
            placeholder="Campo livre"/></Field>
          <Field label="Responsável (em breve)" half><Inp value={f.responsavel}
            onChange={e=>setF(p=>({...p,responsavel:e.target.value}))} placeholder="Ainda de uso pessoal"/></Field>
        </div>

        <div style={{marginTop:16,paddingTop:14,borderTop:"1px solid #f0f0f0"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
            <div style={{fontSize:11,color:"#9ca3af",textTransform:"uppercase",fontWeight:700}}>
              🗺️ Etapas do objetivo <span style={{textTransform:"none",fontWeight:400}}>(opcional — vira um mapa de passos)</span>
            </div>
            {modal!=="novo"&&f.etapas&&f.etapas.length>0&&(
              <button onClick={()=>setDb(prev=>({...prev,centralComando:{...prev.centralComando,
                objetivoAtivoId:prev.centralComando.objetivoAtivoId===f.id?null:f.id}}))}
                style={{background:"none",border:"1px solid #e5e7eb",borderRadius:20,padding:"3px 11px",
                  fontSize:11,fontWeight:700,cursor:"pointer",
                  color:db.centralComando.objetivoAtivoId===f.id?"#5c2030":"#9ca3af"}}>
                {db.centralComando.objetivoAtivoId===f.id?"★ Objetivo ativo na Central":"☆ Definir como ativo na Central"}
              </button>
            )}
          </div>
          <DiagramaObjetivo etapas={f.etapas||[]} onMudar={etapas=>setF(p=>({...p,etapas}))}/>
        </div>

        {modal!=="novo"&&f.historico&&f.historico.length>0&&(
          <div style={{marginTop:16,paddingTop:14,borderTop:"1px solid #f0f0f0"}}>
            <div style={{fontSize:11,color:"#9ca3af",textTransform:"uppercase",fontWeight:700,marginBottom:8}}>Histórico</div>
            <div style={{display:"flex",flexDirection:"column",gap:4,maxHeight:120,overflowY:"auto"}}>
              {[...f.historico].reverse().map((h,i)=>(
                <div key={i} style={{fontSize:12,color:"#6b7280"}}>
                  <span style={{color:"#9ca3af"}}>{fmtData(h.data)}</span> — {h.texto}
                </div>
              ))}
            </div>
          </div>
        )}
        <MBtns onClose={()=>setModal(null)} onSave={salv}/>
      </Modal>}
    </div>
  );
}

// ── FORNECEDOR ────────────────────────────────────────────────
function PageFornecedor({db,setDb}){
  const [modal,setModal]=useState(null);
  const [f,setF]=useState({data:hoje(),cliente:"",time:"",uniforme:"Uniforme 1",tamanho:"M",qtd:1,precoVenda:0,status:"Lista de Espera",custoProduto:0,custoTaxa:0,obs:""});
  const s=(k,v)=>setF(p=>({...p,[k]:v}));const n=(k,v)=>s(k,parseFloat(v)||0);
  const abrirN=()=>{setF({data:hoje(),cliente:"",time:"",uniforme:"Uniforme 1",tamanho:"M",qtd:1,precoVenda:0,status:"Lista de Espera",custoProduto:0,custoTaxa:0,obs:""});setModal("novo");};
  const abrirE=item=>{setF({...item});setModal("editar");};
  const salv=()=>{if(!f.time?.trim())return alert("Informe a camisa.");setDb(prev=>{if(modal==="editar")return{...prev,pedidosFornecedor:prev.pedidosFornecedor.map(p=>p.id===f.id?f:p)};const id=prev.nextId+1;return{...prev,nextId:id,pedidosFornecedor:[...prev.pedidosFornecedor,{...f,id}]};});setModal(null);};
  const del=id=>{if(!window.confirm("Excluir?"))return;setDb(prev=>({...prev,pedidosFornecedor:prev.pedidosFornecedor.filter(p=>p.id!==id)}));};
  const mover=(id,st)=>setDb(prev=>({...prev,pedidosFornecedor:prev.pedidosFornecedor.map(p=>p.id===id?{...p,status:st}:p)}));
  const times=[...new Set([...db.produtos.map(p=>p.time||p.nome).filter(Boolean),...TIMES])].filter((v,i,a)=>a.indexOf(v)===i);
  const grupos=ST_FORN.reduce((acc,st)=>{acc[st]=db.pedidosFornecedor.filter(p=>p.status===st);return acc;},{});
  return(
    <div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:12,marginBottom:16}}>
        {ST_FORN.map(st=><KPI key={st} label={st} value={grupos[st].length} color={st==="Chegou - Vendido"?"#16a34a":"#111"}/>)}
      </div>
      <div style={{display:"flex",justifyContent:"flex-end",marginBottom:16}}><Btn onClick={abrirN}>+ Novo Pedido</Btn></div>
      {db.pedidosFornecedor.length===0&&(
        <Section>
          <Empty msg="Nenhum pedido de fornecedor cadastrado." icon="🚚"/>
        </Section>
      )}
      {ST_FORN.map(st=>grupos[st].length===0?null:(
        <Section key={st} title={<span style={{display:"flex",alignItems:"center",gap:10}}><Badge status={st}/><span style={{fontSize:13,color:"#9ca3af"}}>{grupos[st].length} item{grupos[st].length>1?"s":""}</span></span>}>
          <div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead><tr>{["Data","Cliente","Camisa","Tam.","Qtd","Preço Venda","Custo","Status",""].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
            <tbody>{grupos[st].map(p=>{
              const ct=r(((p.custoProduto||0)+(p.custoTaxa||0))*(p.qtd||1));
              return(
                <HRow key={p.id}>
                  <td style={{...TD,color:"#9ca3af"}}>{fmtData(p.data)}</td>
                  <td style={{...TD,fontWeight:700,color:"#111"}}>{p.cliente||"—"}</td>
                  <td style={TD}>{p.time} {p.uniforme&&<span style={{color:"#9ca3af"}}>({p.uniforme})</span>}</td>
                  <td style={TD}>{p.tamanho}</td>
                  <td style={{...TD,textAlign:"center"}}>{p.qtd}</td>
                  <td style={{...TD,fontWeight:700}}>{brl(p.precoVenda)}</td>
                  <td style={TD}>{brl(ct)}</td>
                  <td style={TD}>
                    <select value={p.status} onChange={e=>mover(p.id,e.target.value)}
                      style={{...INP,width:160,padding:"5px 8px",fontSize:12}}>
                      {ST_FORN.map(s2=><option key={s2}>{s2}</option>)}
                    </select>
                  </td>
                  <td style={TD}><div style={{display:"flex",gap:5}}>
                    <Btn v="sm" onClick={()=>abrirE(p)}>✏</Btn>
                    <Btn v="danger" onClick={()=>del(p.id)}>🗑</Btn>
                  </div></td>
                </HRow>
              );
            })}</tbody>
          </table></div>
        </Section>
      ))}
      {(modal==="novo"||modal==="editar")&&(
        <Modal title={modal==="editar"?"Editar Pedido Fornecedor":"Novo Pedido Fornecedor"} onClose={()=>setModal(null)}>
          <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
            <Field label="Data" half><Inp type="date" value={f.data} onChange={e=>s("data",e.target.value)}/></Field>
            <Field label="Status" half><Sel value={f.status} onChange={e=>s("status",e.target.value)}>{ST_FORN.map(st=><option key={st}>{st}</option>)}</Sel></Field>
            <Field label="Cliente (opcional)"><Inp value={f.cliente} onChange={e=>s("cliente",e.target.value)} placeholder="Se já tem cliente reservado"/></Field>
            <Field label="Time / Camisa" half>
              <Inp list="lst-tf" value={f.time} onChange={e=>s("time",e.target.value)} placeholder="ex: Bahia" autoFocus/>
              <datalist id="lst-tf">{times.map(t=><option key={t} value={t}/>)}</datalist>
            </Field>
            <Field label="Uniforme" half><Sel value={f.uniforme} onChange={e=>s("uniforme",e.target.value)}>{UNIFORMES.map(u=><option key={u}>{u}</option>)}</Sel></Field>
            <Field label="Tamanho" third><Sel value={f.tamanho} onChange={e=>s("tamanho",e.target.value)}>{TAMANHOS.map(t=><option key={t}>{t}</option>)}</Sel></Field>
            <Field label="Quantidade" third><Inp type="number" min="1" value={f.qtd} onChange={e=>n("qtd",e.target.value)}/></Field>
            <Field label="Preço de Venda" third><Inp type="number" min="0" step="0.01" value={f.precoVenda} onChange={e=>n("precoVenda",e.target.value)}/></Field>
            <Field label="Custo Produto" half><Inp type="number" min="0" step="0.01" value={f.custoProduto} onChange={e=>n("custoProduto",e.target.value)}/></Field>
            <Field label="Custo Taxa" half><Inp type="number" min="0" step="0.01" value={f.custoTaxa} onChange={e=>n("custoTaxa",e.target.value)}/></Field>
            <Field label="Observação"><Inp value={f.obs} onChange={e=>s("obs",e.target.value)} placeholder="ex: encomenda especial..."/></Field>
          </div>
          <MBtns onClose={()=>setModal(null)} onSave={salv}/>
        </Modal>
      )}
    </div>
  );
}
// ── ECOSSISTEMA — novas fontes de renda além das camisas ───────
const STATUS_PROJETO=["Planejamento","Em Andamento","Ativo","Pausado"];
const COR_STATUS_PROJETO={Planejamento:"#9ca3af",["Em Andamento"]:"#2563eb",Ativo:"#16a34a",Pausado:"#dc2626"};

function CardProjeto({projeto,setDb,onDelete}){
  const [novaEtapa,setNovaEtapa]=useState("");
  const [editandoDesc,setEditandoDesc]=useState(false);
  const [desc,setDesc]=useState(projeto.descricao);
  const total=projeto.etapas.length;
  const feitas=projeto.etapas.filter(e=>e.feita).length;
  const prog=total>0?Math.round((feitas/total)*100):null;

  const atualizar=patch=>setDb(prev=>({...prev,ecossistema:{...prev.ecossistema,
    projetos:prev.ecossistema.projetos.map(p=>p.id===projeto.id?{...p,...patch}:p)}}));

  const toggleEtapa=eid=>atualizar({etapas:projeto.etapas.map(e=>e.id===eid?{...e,feita:!e.feita}:e)});
  const delEtapa=eid=>atualizar({etapas:projeto.etapas.filter(e=>e.id!==eid)});
  const addEtapa=()=>{
    if(!novaEtapa.trim())return;
    const proxId=(projeto.etapas.reduce((m,e)=>Math.max(m,e.id),0)||0)+1;
    atualizar({etapas:[...projeto.etapas,{id:proxId,titulo:novaEtapa.trim(),feita:false}]});
    setNovaEtapa("");
  };
  const salvarDesc=()=>{atualizar({descricao:desc});setEditandoDesc(false);};

  return(
    <div style={{background:"#fff",border:"1px solid #e5e7eb",borderRadius:12,padding:"18px 20px"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10,marginBottom:8}}>
        <div style={{fontSize:16,fontWeight:800,color:"#111"}}>{projeto.nome}</div>
        <div style={{display:"flex",gap:8,alignItems:"center",flexShrink:0}}>
          <select value={projeto.status} onChange={e=>atualizar({status:e.target.value})}
            style={{fontSize:11,fontWeight:700,color:COR_STATUS_PROJETO[projeto.status],
              background:"#f9fafb",border:`1px solid ${COR_STATUS_PROJETO[projeto.status]}55`,
              borderRadius:20,padding:"4px 10px",cursor:"pointer"}}>
            {STATUS_PROJETO.map(s=><option key={s} value={s}>{s}</option>)}
          </select>
          <Btn v="danger" onClick={()=>onDelete(projeto.id)}>🗑</Btn>
        </div>
      </div>

      {editandoDesc?(
        <input autoFocus value={desc} onChange={e=>setDesc(e.target.value)}
          onBlur={salvarDesc} onKeyDown={e=>{if(e.key==="Enter")salvarDesc();}}
          style={{...INP,marginBottom:10}}/>
      ):(
        <div onClick={()=>setEditandoDesc(true)} style={{fontSize:13,color:"#6b7280",marginBottom:10,cursor:"pointer"}}>
          {projeto.descricao||"Clique para adicionar uma descrição"}
        </div>
      )}

      {prog!==null&&(
        <div style={{marginBottom:12}}>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:11,color:"#9ca3af",marginBottom:4}}>
            <span>Progresso</span><span>{feitas}/{total} etapas · {prog}%</span>
          </div>
          <div style={{height:6,background:"#f3f4f6",borderRadius:4,overflow:"hidden"}}>
            <div style={{width:`${prog}%`,height:"100%",background:"#5c2030",transition:"width 0.3s"}}/>
          </div>
        </div>
      )}

      {total>0&&(
        <div style={{display:"flex",flexDirection:"column",gap:6,marginBottom:10}}>
          {projeto.etapas.map(e=>{
            const [h,setH]=useState(false);
            return(
              <div key={e.id} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
                style={{display:"flex",alignItems:"center",gap:10,padding:"6px 4px",borderRadius:6,
                  background:h?"#f9fafb":"transparent"}}>
                <button onClick={()=>toggleEtapa(e.id)} style={{width:18,height:18,borderRadius:5,
                  border:`2px solid ${e.feita?"#16a34a":"#d1d5db"}`,background:e.feita?"#16a34a":"none",
                  cursor:"pointer",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",
                  color:"#fff",fontSize:11}}>{e.feita?"✓":""}</button>
                <span style={{flex:1,fontSize:13,color:e.feita?"#9ca3af":"#374151",
                  textDecoration:e.feita?"line-through":"none"}}>{e.titulo}</span>
                {h&&<span onClick={()=>delEtapa(e.id)} style={{cursor:"pointer",color:"#d1d5db",fontSize:13}}>✕</span>}
              </div>
            );
          })}
        </div>
      )}

      <div style={{display:"flex",gap:8}}>
        <input value={novaEtapa} onChange={e=>setNovaEtapa(e.target.value)}
          onKeyDown={e=>{if(e.key==="Enter")addEtapa();}}
          placeholder="+ nova etapa" style={{...INP,fontSize:12,padding:"7px 10px"}}/>
        <Btn v="sm" onClick={addEtapa}>Add</Btn>
      </div>
    </div>
  );
}

function PageEcossistema({db,setDb}){
  const [modal,setModal]=useState(false);
  const [f,setF]=useState({nome:"",descricao:""});
  const projetos=db.ecossistema.projetos;
  const totalEtapas=projetos.reduce((a,p)=>a+p.etapas.length,0);
  const etapasFeitas=projetos.reduce((a,p)=>a+p.etapas.filter(e=>e.feita).length,0);
  const emAndamento=projetos.filter(p=>p.status==="Em Andamento"||p.status==="Ativo").length;

  const addProjeto=()=>{
    if(!f.nome.trim())return alert("Dê um nome ao projeto.");
    setDb(prev=>{
      const proxId=(prev.ecossistema.projetos.reduce((m,p)=>Math.max(m,p.id),0)||0)+1;
      return{...prev,ecossistema:{...prev.ecossistema,projetos:[...prev.ecossistema.projetos,
        {id:proxId,nome:f.nome.trim(),descricao:f.descricao.trim(),status:"Planejamento",etapas:[]}]}};
    });
    setF({nome:"",descricao:""});setModal(false);
  };
  const delProjeto=id=>{
    if(!window.confirm("Excluir este projeto e todas as etapas dele?"))return;
    setDb(prev=>({...prev,ecossistema:{...prev.ecossistema,
      projetos:prev.ecossistema.projetos.filter(p=>p.id!==id)}}));
  };

  return(
    <div>
      <div style={{marginBottom:16}}>
        <div style={{fontSize:22,fontWeight:800,color:"#111"}}>Ecossistema</div>
        <div style={{fontSize:13,color:"#9ca3af"}}>Novas fontes de renda além das camisas</div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(3,minmax(0,1fr))",gap:12,marginBottom:16}}>
        <KPI label="Projetos" value={projetos.length} color="#111"/>
        <KPI label="Em andamento / ativos" value={emAndamento} color="#2563eb"/>
        <KPI label="Etapas concluídas" value={`${etapasFeitas}/${totalEtapas}`} color="#16a34a"/>
      </div>

      <div style={{display:"flex",justifyContent:"flex-end",marginBottom:16}}>
        <Btn onClick={()=>setModal(true)}>+ Novo Projeto</Btn>
      </div>

      {projetos.length===0?<Empty msg="Nenhum projeto cadastrado ainda." icon="🚀"/>:(
        <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:14}}>
          {projetos.map(p=><CardProjeto key={p.id} projeto={p} setDb={setDb} onDelete={delProjeto}/>)}
        </div>
      )}

      {modal&&<Modal title="Novo Projeto" onClose={()=>setModal(false)}>
        <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
          <Field label="Nome do projeto"><Inp value={f.nome} onChange={e=>setF(p=>({...p,nome:e.target.value}))}
            placeholder="ex: Loja de acessórios" autoFocus/></Field>
          <Field label="Descrição (opcional)"><Inp value={f.descricao} onChange={e=>setF(p=>({...p,descricao:e.target.value}))}
            placeholder="Do que se trata esse projeto?"/></Field>
        </div>
        <MBtns onClose={()=>setModal(false)} onSave={addProjeto}/>
      </Modal>}
    </div>
  );
}
// ── CRM — cadastro de clientes, histórico e linha do tempo ──────
const CLIENTE_VAZIO={nome:"",telefone:"",cidade:"",instagram:"",observacoes:"",origem:"Futebol",
  status:"Ativo",creditoLimite:0,valorEmAberto:0,situacaoPagamento:"Neutro",estagioComercial:"Interessado"};

function ModalCliente({inicial,onClose,onSave}){
  const [f,setF]=useState(inicial?{...CLIENTE_VAZIO,...inicial}:{...CLIENTE_VAZIO});
  const s=(k,v)=>setF(p=>({...p,[k]:v}));
  const salvar=()=>{
    if(!f.nome.trim())return alert("Informe o nome.");
    if(!f.origem)return alert("Origem é obrigatória — é o que vamos medir.");
    onSave(f);
  };
  return(
    <Modal title={inicial?"Editar Cliente":"Novo Cliente"} onClose={onClose} wide>
      <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
        <Field label="Nome" half><Inp value={f.nome} onChange={e=>s("nome",e.target.value)} autoFocus/></Field>
        <Field label="Telefone" half><Inp value={f.telefone} onChange={e=>s("telefone",e.target.value)} placeholder="(xx) xxxxx-xxxx"/></Field>
        <Field label="Cidade" third><Inp value={f.cidade} onChange={e=>s("cidade",e.target.value)}/></Field>
        <Field label="Instagram (opcional)" third><Inp value={f.instagram} onChange={e=>s("instagram",e.target.value)} placeholder="@usuario"/></Field>
        <Field label="Origem" third><Sel value={f.origem} onChange={e=>s("origem",e.target.value)}>
          {ORIGENS_CLIENTE.map(o=><option key={o}>{o}</option>)}</Sel></Field>
        <Field label="Estágio comercial" third><Sel value={f.estagioComercial} onChange={e=>s("estagioComercial",e.target.value)}>
          {ESTAGIOS_COMERCIAIS.map(o=><option key={o}>{o}</option>)}</Sel></Field>
        <Field label="Observações"><Inp value={f.observacoes} onChange={e=>s("observacoes",e.target.value)}
          placeholder='Ex: "Prefere tamanho G", "Paga no Pix"'/></Field>
        <Field label="Status" third><Sel value={f.status} onChange={e=>s("status",e.target.value)}>
          {STATUS_CLIENTE.map(o=><option key={o}>{o}</option>)}</Sel></Field>
        <Field label="Limite de crédito" third><Inp type="number" min="0" value={f.creditoLimite}
          onChange={e=>s("creditoLimite",Number(e.target.value)||0)}/></Field>
        <Field label="Valor em aberto" third><Inp type="number" min="0" value={f.valorEmAberto}
          onChange={e=>s("valorEmAberto",Number(e.target.value)||0)}/></Field>
        <Field label="Situação de pagamento" half><Sel value={f.situacaoPagamento} onChange={e=>s("situacaoPagamento",e.target.value)}>
          {SITUACAO_PAGAMENTO.map(o=><option key={o}>{o}</option>)}</Sel></Field>
      </div>
      <MBtns onClose={onClose} onSave={salvar}/>
    </Modal>
  );
}

function ModalTarefaCliente({cliente,onClose,onSave}){
  const [f,setF]=useState({titulo:"",categoria:"Operacional",urgencia:"Média",prazo:""});
  const s=(k,v)=>setF(p=>({...p,[k]:v}));
  const salvar=()=>{if(!f.titulo.trim())return alert("Informe o título.");onSave(f);};
  return(
    <Modal title={`Nova tarefa — ${cliente.nome}`} onClose={onClose}>
      <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
        <Field label="Título"><Inp value={f.titulo} onChange={e=>s("titulo",e.target.value)}
          placeholder='Ex: "Avisar chegada Bahia"' autoFocus/></Field>
        <Field label="Categoria" third><Sel value={f.categoria} onChange={e=>s("categoria",e.target.value)}>
          {CATEGORIAS_WORK.map(c=><option key={c}>{c}</option>)}</Sel></Field>
        <Field label="Urgência" third><Sel value={f.urgencia} onChange={e=>s("urgencia",e.target.value)}>
          {URGENCIAS_WORK.map(u=><option key={u}>{u}</option>)}</Sel></Field>
        <Field label="Prazo" third><Inp type="date" value={f.prazo} onChange={e=>s("prazo",e.target.value)}/></Field>
      </div>
      <MBtns onClose={onClose} onSave={salvar}/>
    </Modal>
  );
}

function PageClienteDetalhe({cliente,db,setDb,onVoltar,onNavigate}){
  const [modalEdit,setModalEdit]=useState(false);
  const [modalTarefa,setModalTarefa]=useState(false);
  const historico=pedidosDoCliente(cliente,db.pedidos).sort((a,b)=>(b.data||"").localeCompare(a.data||""));
  const timeline=timelineCliente(cliente,db.pedidos).reverse();
  const tarefasCliente=db.tarefas.filter(t=>t.clienteId===cliente.id);

  // Resumo — tudo calculado a partir dos Pedidos, nada digitado de novo aqui.
  const totalCompras=historico.length;
  const totalGasto=r(historico.reduce((a,p)=>a+(p.precoVenda||0)*(p.qtd||1),0));
  const lucroGerado=r(historico.reduce((a,p)=>a+lucroPedido(p),0));
  const ticketMedio=totalCompras>0?r(totalGasto/totalCompras):0;
  const dataUltimaCompra=ultimaCompraCliente(cliente,db.pedidos);

  const salvarEdit=f=>{
    setDb(prev=>({...prev,clientes:prev.clientes.map(c=>c.id===cliente.id?{...c,...f}:c)}));
    setModalEdit(false);
  };
  const criarTarefa=f=>{
    setDb(prev=>{const id=prev.nextId+1;return{...prev,nextId:id,tarefas:[...prev.tarefas,
      {id,titulo:f.titulo,descricao:"",categoria:f.categoria,urgencia:f.urgencia,prazo:f.prazo,
        status:"Pendente",responsavel:"",recorrencia:"Nenhuma",clienteId:cliente.id,clienteNome:cliente.nome}]};});
    setModalTarefa(false);
  };

  const tile=(label,value,color="#111")=>(
    <div style={{background:"#f9fafb",border:"1px solid #f0f0f0",borderRadius:8,padding:"10px 12px"}}>
      <div style={{fontSize:10.5,color:"#9ca3af",marginBottom:3,textTransform:"uppercase",letterSpacing:"0.3px"}}>{label}</div>
      <div style={{fontSize:14,fontWeight:700,color}}>{value}</div>
    </div>
  );

  return(
    <div>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}>
        <button onClick={onVoltar} style={{background:"none",border:"none",color:"#6b7280",
          fontSize:13,cursor:"pointer",padding:0,marginBottom:8,display:"flex",alignItems:"center",gap:4}}>
          ← Voltar para Clientes
        </button>
        <Btn onClick={()=>setModalEdit(true)}>✎ Editar</Btn>
      </div>

      <div style={{background:"#fff",border:"1px solid #e5e7eb",borderRadius:12,padding:"18px 20px",marginBottom:16}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:12,marginBottom:16}}>
          <div>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <div style={{fontSize:20,fontWeight:800,color:"#111"}}>{cliente.nome}</div>
              <span style={{fontSize:11,fontWeight:700,color:COR_ESTAGIO_COMERCIAL[cliente.estagioComercial],
                background:"#f9fafb",border:`1px solid ${COR_ESTAGIO_COMERCIAL[cliente.estagioComercial]}55`,
                borderRadius:20,padding:"2px 9px"}}>{cliente.estagioComercial}</span>
            </div>
            <div style={{fontSize:13,color:"#6b7280",marginTop:4}}>
              {cliente.telefone&&<>📞 {cliente.telefone} · </>}Status: <b>{cliente.status}</b>
            </div>
            {cliente.observacoes&&<div style={{fontSize:13,color:"#374151",marginTop:8,fontStyle:"italic"}}>
              "{cliente.observacoes}"</div>}
          </div>
          {cliente.valorEmAberto>0&&<span style={{fontSize:11,fontWeight:700,padding:"4px 10px",
            borderRadius:20,background:"#fef2f2",border:"1px solid #fecaca",color:"#dc2626",flexShrink:0}}>
            Deve {brl(cliente.valorEmAberto)}</span>}
        </div>

        <div style={{fontSize:11,color:"#9ca3af",marginBottom:8,textTransform:"uppercase",
          letterSpacing:"0.4px",fontWeight:700}}>📊 Resumo</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,minmax(0,1fr))",gap:8}}>
          {tile("Nome",cliente.nome)}
          {tile("Origem",cliente.origem)}
          {tile("Cliente desde",fmtData(cliente.criadoEm))}
          {tile("Última compra",dataUltimaCompra?fmtData(dataUltimaCompra):"—")}
          {tile("Total gasto",brl(totalGasto))}
          {tile("Lucro gerado",brl(lucroGerado),lucroGerado>=0?"#16a34a":"#dc2626")}
          {tile("Nº de compras",totalCompras)}
          {tile("Ticket médio",brl(ticketMedio))}
          {tile("Situação",cliente.situacaoPagamento,COR_SITUACAO_PAGAMENTO[cliente.situacaoPagamento])}
        </div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1.3fr 1fr",gap:16}}>
        <div style={{display:"flex",flexDirection:"column",gap:16}}>
          <Section title="🧾 Histórico de Compras">
            {historico.length===0?<Empty msg="Nenhuma compra registrada ainda." icon="🛒"/>:(
              <table style={{width:"100%",borderCollapse:"collapse"}}>
                <thead><tr>
                  <th style={TDSM_TH}>Data</th><th style={TDSM_TH}>Produto</th>
                  <th style={TDSM_TH}>Valor</th><th style={TDSM_TH}>Lucro</th><th style={TDSM_TH}>Situação</th>
                </tr></thead>
                <tbody>{historico.map(p=>(
                  <tr key={p.id}>
                    <td style={TDSM}>{fmtData(p.data)}</td>
                    <td style={TDSM}>{p.time||p.camisa}{p.uniforme?` (${p.uniforme})`:""} · {p.tamanho}</td>
                    <td style={TDSM}>{brl((p.precoVenda||0)*(p.qtd||1))}</td>
                    <td style={{...TDSM,color:lucroPedido(p)>=0?"#16a34a":"#dc2626",fontWeight:700}}>{brl(lucroPedido(p))}</td>
                    <td style={TDSM}><Badge status={p.status}/></td>
                  </tr>
                ))}</tbody>
              </table>
            )}
          </Section>

          <Section title="🕓 Linha do Tempo">
            {timeline.length===0?<Empty msg="Nenhum evento ainda." icon="🕓"/>:(
              <div style={{display:"flex",flexDirection:"column",gap:2}}>
                {timeline.map((e,i)=>(
                  <div key={i} style={{display:"flex",gap:12,padding:"8px 0",
                    borderBottom:i<timeline.length-1?"1px solid #f5f5f5":"none"}}>
                    <div style={{fontSize:12,color:"#9ca3af",width:80,flexShrink:0}}>{fmtData(e.data)}</div>
                    <div style={{fontSize:13,color:"#374151"}}>{e.texto}</div>
                  </div>
                ))}
              </div>
            )}
          </Section>
        </div>

        <div style={{display:"flex",flexDirection:"column",gap:16}}>
          <Section title="💻 Work" action={<Btn onClick={()=>setModalTarefa(true)}>➕</Btn>}>
            {tarefasCliente.length===0?<div style={{fontSize:13,color:"#9ca3af"}}>Nenhuma tarefa ligada a este cliente.</div>:(
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {ordenarTarefasPorPrioridade(tarefasCliente).map(t=>(
                  <div key={t.id} onClick={()=>onNavigate&&onNavigate("tarefas")} style={{fontSize:13,
                    padding:"8px 10px",background:"#f9fafb",borderRadius:8,cursor:"pointer",
                    borderLeft:`3px solid ${COR_URGENCIA_WORK[t.urgencia]}`}}>
                    <div style={{fontWeight:600,color:"#111",
                      textDecoration:t.status==="Concluído"?"line-through":"none"}}>{t.titulo}</div>
                    <div style={{fontSize:11,color:"#9ca3af",marginTop:2}}>{t.status} · {t.categoria}</div>
                  </div>
                ))}
              </div>
            )}
          </Section>

          <Section title="🧠 Inteligência">
            <div style={{fontSize:13,color:"#9ca3af"}}>Ainda não há dados suficientes.</div>
          </Section>
        </div>
      </div>

      {modalEdit&&<ModalCliente inicial={cliente} onClose={()=>setModalEdit(false)} onSave={salvarEdit}/>}
      {modalTarefa&&<ModalTarefaCliente cliente={cliente} onClose={()=>setModalTarefa(false)} onSave={criarTarefa}/>}
    </div>
  );
}

function PageCRM({db,setDb,onNavigate}){
  const [selecionado,setSelecionado]=useState(null);
  const [modal,setModal]=useState(false);
  const [busca,setBusca]=useState("");
  const [filtro,setFiltro]=useState("todos");

  const clienteAtual=selecionado?db.clientes.find(c=>c.id===selecionado):null;
  if(clienteAtual){
    return <PageClienteDetalhe cliente={clienteAtual} db={db} setDb={setDb} onNavigate={onNavigate}
      onVoltar={()=>setSelecionado(null)}/>;
  }

  const compras=c=>pedidosDoCliente(c,db.pedidos).length;
  const totalClientes=db.clientes.length;
  const ativos90=db.clientes.filter(c=>situacaoRecenciaCliente(c,db.pedidos)==="Ativo").length;
  const recorrentes=db.clientes.filter(c=>compras(c)>=2).length;
  const novosNoMes=db.clientes.filter(c=>(c.criadoEm||"").startsWith(mesAtual())).length;

  // "Quem preciso chamar hoje" — leads/interessados ainda não convertidos, e
  // clientes que já compraram mas sumiram (candidatos a recompra).
  const chamarHoje=[
    ...db.clientes.filter(c=>c.estagioComercial==="Lead"||c.estagioComercial==="Interessado"),
    ...db.clientes.filter(c=>c.estagioComercial==="Cliente"&&situacaoRecenciaCliente(c,db.pedidos)==="Inativo"),
  ].slice(0,6);

  const FILTROS=[{k:"todos",l:"Todos"},{k:"leads",l:"Leads/Interessados"},{k:"ativos",l:"Ativos"},
    {k:"inativos",l:"Inativos"},{k:"vip",l:"VIP"},{k:"devendo",l:"Devendo"},{k:"recorrentes",l:"Recorrentes"}];

  const filtrados=db.clientes.filter(c=>{
    const s=situacaoRecenciaCliente(c,db.pedidos);
    if(filtro==="leads"&&c.estagioComercial==="Cliente")return false;
    if(filtro==="ativos"&&s!=="Ativo")return false;
    if(filtro==="inativos"&&s!=="Inativo")return false;
    if(filtro==="vip"&&compras(c)<5)return false;
    if(filtro==="devendo"&&!(c.valorEmAberto>0))return false;
    if(filtro==="recorrentes"&&compras(c)<2)return false;
    if(busca.trim()){
      const q=busca.trim().toLowerCase();
      if(!(c.nome||"").toLowerCase().includes(q)&&!(c.telefone||"").includes(busca.trim()))return false;
    }
    return true;
  });

  const salvarNovo=f=>{
    setDb(prev=>{
      const id=(prev.clientes.reduce((m,c)=>Math.max(m,c.id),0)||0)+1;
      const novo={...f,id,criadoEm:hoje(),timeline:[{id:1,data:hoje(),texto:"Cliente cadastrado"}]};
      return{...prev,clientes:[...prev.clientes,novo]};
    });
    setModal(false);
  };

  return(
    <div>
      <div style={{marginBottom:16}}>
        <div style={{fontSize:22,fontWeight:800,color:"#111"}}>CRM</div>
        <div style={{fontSize:13,color:"#9ca3af"}}>Quem é, como chegou, o que comprou, se pagou</div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:12,marginBottom:16}}>
        <KPI label="👥 Clientes" value={totalClientes} color="#111"/>
        <KPI label="🟢 Ativos (90 dias)" value={ativos90} color="#16a34a"/>
        <KPI label="⭐ Recorrentes" value={recorrentes} color="#2563eb"/>
        <KPI label="🆕 Novos no mês" value={novosNoMes} color="#d4af37"/>
      </div>

      {chamarHoje.length>0&&(
        <Section title="📞 Quem chamar hoje">
          <table style={{width:"100%",borderCollapse:"collapse"}}>
            <tbody>
              {chamarHoje.map(c=>(
                <HRow key={c.id} onClick={()=>setSelecionado(c.id)}>
                  <td style={{...TDSM,fontWeight:700,color:"#111",width:"30%"}}>{c.nome}</td>
                  <td style={TDSM}>
                    <span style={{fontSize:11,fontWeight:700,color:COR_ESTAGIO_COMERCIAL[c.estagioComercial],
                      background:"#f9fafb",border:`1px solid ${COR_ESTAGIO_COMERCIAL[c.estagioComercial]}55`,
                      borderRadius:20,padding:"2px 9px"}}>{c.estagioComercial}</span>
                  </td>
                  <td style={{...TDSM,color:"#9ca3af"}}>
                    {c.estagioComercial==="Cliente"?"Sem comprar há mais de 90 dias":"Ainda não converteu — fazer follow-up"}
                  </td>
                </HRow>
              ))}
            </tbody>
          </table>
        </Section>
      )}

      <Section action={
        <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
          <Inp value={busca} onChange={e=>setBusca(e.target.value)} placeholder="Nome ou telefone..."
            style={{width:180}}/>
          <Tabs options={FILTROS} value={filtro} onChange={setFiltro}/>
          <Btn onClick={()=>setModal(true)}>➕ Novo Cliente</Btn>
        </div>
      }>
        {filtrados.length===0?<Empty msg="Nenhum cliente encontrado." icon="👥"/>:(
          <table style={{width:"100%",borderCollapse:"collapse"}}>
            <thead><tr>
              <th style={TDSM_TH}>Nome</th><th style={TDSM_TH}>Estágio</th><th style={TDSM_TH}>Origem</th>
              <th style={TDSM_TH}>Última compra</th><th style={TDSM_TH}>Compras</th><th style={TDSM_TH}>Situação</th>
            </tr></thead>
            <tbody>{filtrados.map(c=>{
              const ultima=ultimaCompraCliente(c,db.pedidos);
              const dias=diasDesde(ultima);
              const s=situacaoRecenciaCliente(c,db.pedidos);
              return(
                <HRow key={c.id} onClick={()=>setSelecionado(c.id)}>
                  <td style={{...TDSM,fontWeight:700,color:"#111"}}>{c.nome}</td>
                  <td style={TDSM}>
                    <span style={{fontSize:10.5,fontWeight:700,color:COR_ESTAGIO_COMERCIAL[c.estagioComercial]}}>
                      {c.estagioComercial}</span>
                  </td>
                  <td style={TDSM}>{c.origem}</td>
                  <td style={TDSM}>{dias===null?"—":`${dias} dias`}</td>
                  <td style={TDSM}>{compras(c)}</td>
                  <td style={TDSM}>{s==="Ativo"?"🟢 Ativo":"⚪ Inativo"}</td>
                </HRow>
              );
            })}</tbody>
          </table>
        )}
      </Section>

      {modal&&<ModalCliente onClose={()=>setModal(false)} onSave={salvarNovo}/>}
    </div>
  );
}

// ── ACADEMIA — Sistema de Formação Empresarial ──────────────────
const MEDALHA_CUSTO={"Gratuito":"🥇","Baixo custo":"🥈","Premium":"🥉"};
const COR_CUSTO={"Gratuito":"#16a34a","Baixo custo":"#ca8a04","Premium":"#7c3aed"};

function CardFerramenta({f}){
  return(
    <div style={{background:"#fff",border:"1px solid #e5e7eb",borderRadius:10,padding:"14px 16px"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:6}}>
        <div style={{fontSize:14,fontWeight:800,color:"#111"}}>{f.nome}</div>
        <span style={{fontSize:11,fontWeight:700,color:COR_CUSTO[f.custo],background:"#f9fafb",
          border:`1px solid ${COR_CUSTO[f.custo]}33`,borderRadius:20,padding:"2px 9px",flexShrink:0}}>
          {MEDALHA_CUSTO[f.custo]} {f.custo}
        </span>
      </div>
      {f.funcao&&<div style={{fontSize:12.5,color:"#374151",marginBottom:6}}>{f.funcao}</div>}
      {f.quandoUsar&&<div style={{fontSize:12,color:"#6b7280",marginBottom:4}}><b>Quando usar:</b> {f.quandoUsar}</div>}
      {f.pontosFortes&&<div style={{fontSize:12,color:"#16a34a",marginBottom:4}}><b>Pontos fortes:</b> {f.pontosFortes}</div>}
      {f.limitacoes&&<div style={{fontSize:12,color:"#ca8a04",marginBottom:4}}><b>Limitações:</b> {f.limitacoes}</div>}
      {f.comoAjudaT11&&<div style={{fontSize:12,color:"#5c2030",marginBottom:4}}><b>Na T11:</b> {f.comoAjudaT11}</div>}
      {f.casosReais&&<div style={{fontSize:11.5,color:"#9ca3af",fontStyle:"italic"}}>Ex: {f.casosReais}</div>}
    </div>
  );
}

function ModalFerramenta({onClose,onSave}){
  const [f,setF]=useState({nome:"",custo:"Gratuito",funcao:"",quandoUsar:"",pontosFortes:"",
    limitacoes:"",comoAjudaT11:"",casosReais:"",nivel:"Fácil"});
  const s=(k,v)=>setF(p=>({...p,[k]:v}));
  return(
    <Modal title="Nova Ferramenta" onClose={onClose} wide>
      <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
        <Field label="Nome" half><Inp value={f.nome} onChange={e=>s("nome",e.target.value)} autoFocus/></Field>
        <Field label="Custo" half><Sel value={f.custo} onChange={e=>s("custo",e.target.value)}>
          {["Gratuito","Baixo custo","Premium"].map(c=><option key={c}>{c}</option>)}</Sel></Field>
        <Field label="Função"><Inp value={f.funcao} onChange={e=>s("funcao",e.target.value)}/></Field>
        <Field label="Quando usar"><Inp value={f.quandoUsar} onChange={e=>s("quandoUsar",e.target.value)}/></Field>
        <Field label="Pontos fortes"><Inp value={f.pontosFortes} onChange={e=>s("pontosFortes",e.target.value)}/></Field>
        <Field label="Limitações"><Inp value={f.limitacoes} onChange={e=>s("limitacoes",e.target.value)}/></Field>
        <Field label="Como ajuda a T11"><Inp value={f.comoAjudaT11} onChange={e=>s("comoAjudaT11",e.target.value)}/></Field>
        <Field label="Caso real de uso"><Inp value={f.casosReais} onChange={e=>s("casosReais",e.target.value)}/></Field>
      </div>
      <MBtns onClose={onClose} onSave={()=>{if(!f.nome.trim())return alert("Informe o nome.");onSave(f);}}/>
    </Modal>
  );
}

function LinhaAula({aula,onToggle,onSalvarDetalhes}){
  const [aberta,setAberta]=useState(false);
  const [resumo,setResumo]=useState(aula.resumo);
  const [obs,setObs]=useState(aula.observacoes);
  return(
    <div style={{border:"1px solid #e5e7eb",borderRadius:9,background:aula.concluida?"#fafafa":"#fff"}}>
      <div style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px"}}>
        <button onClick={()=>onToggle(aula.id)} style={{width:20,height:20,borderRadius:6,
          border:`2px solid ${aula.concluida?"#16a34a":"#d1d5db"}`,background:aula.concluida?"#16a34a":"none",
          cursor:"pointer",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",
          color:"#fff",fontSize:11}}>{aula.concluida?"✓":""}</button>
        <div onClick={()=>setAberta(a=>!a)} style={{flex:1,cursor:"pointer",fontSize:13.5,fontWeight:600,
          color:"#111",textDecoration:aula.concluida?"line-through":"none"}}>{aula.titulo}</div>
        <span style={{fontSize:11,color:"#9ca3af",flexShrink:0}}>+{aula.xp} XP</span>
      </div>
      {aberta&&(
        <div style={{padding:"0 12px 12px 42px",display:"flex",flexDirection:"column",gap:8}}>
          <div>
            <div style={{fontSize:10.5,color:"#9ca3af",marginBottom:3,textTransform:"uppercase"}}>Resumo</div>
            <textarea value={resumo} onChange={e=>setResumo(e.target.value)}
              onBlur={()=>onSalvarDetalhes(aula.id,{resumo})}
              placeholder="O que você aprendeu?" rows={2}
              style={{...INP,fontFamily:"inherit",resize:"vertical"}}/>
          </div>
          <div>
            <div style={{fontSize:10.5,color:"#9ca3af",marginBottom:3,textTransform:"uppercase"}}>Observações</div>
            <textarea value={obs} onChange={e=>setObs(e.target.value)}
              onBlur={()=>onSalvarDetalhes(aula.id,{observacoes:obs})}
              placeholder="Anotações livres" rows={2}
              style={{...INP,fontFamily:"inherit",resize:"vertical"}}/>
          </div>
        </div>
      )}
    </div>
  );
}

function PageModuloAcademia({modulo,db,setDb,onVoltar,onNavigate}){
  const [aba,setAba]=useState("conteudo");
  const [modalFerramenta,setModalFerramenta]=useState(false);
  const [novaAplicacao,setNovaAplicacao]=useState("");
  const [novoBib,setNovoBib]=useState({titulo:"",tipo:"Link",url:"",nota:""});

  const atualizarModulo=patch=>setDb(prev=>({...prev,academia:{...prev.academia,
    modulos:prev.academia.modulos.map(m=>m.id===modulo.id?{...m,...patch}:m)}}));

  const toggleAula=aulaId=>{
    const aula=modulo.aulas.find(a=>a.id===aulaId);
    const concluida=!aula.concluida;
    const aulas=modulo.aulas.map(a=>a.id===aulaId?{...a,concluida}:a);
    setDb(prev=>{
      let academia={...prev.academia,modulos:prev.academia.modulos.map(m=>m.id===modulo.id?{...m,aulas}:m)};
      const delta=concluida?1:-1;
      academia.xp=Math.max(0,academia.xp+delta*(aula.xp||50));
      academia.tempoTotalMin=Math.max(0,academia.tempoTotalMin+delta*(aula.tempoEstimadoMin||15));
      if(concluida)academia=registrarEstudoAcademia(academia);
      return{...prev,academia};
    });
  };
  const salvarDetalhesAula=(aulaId,patch)=>atualizarModulo({aulas:modulo.aulas.map(a=>a.id===aulaId?{...a,...patch}:a)});

  const addFerramenta=f=>{atualizarModulo({ferramentas:[...modulo.ferramentas,{...f,id:Date.now()}]});setModalFerramenta(false);};

  const addAplicacao=()=>{
    if(!novaAplicacao.trim())return;
    atualizarModulo({aplicacoes:[...modulo.aplicacoes,{id:Date.now(),texto:novaAplicacao.trim(),data:hoje(),enviadaParaWork:false}]});
    setNovaAplicacao("");
  };
  const enviarParaWork=aplicacao=>{
    setDb(prev=>{
      const id=prev.nextId+1;
      const categoria=CATEGORIAS_WORK.includes(modulo.nome)?modulo.nome:"Estratégia";
      const tarefa={id,titulo:`Aplicar: ${aplicacao.texto}`,descricao:`Vindo da Academia — módulo ${modulo.nome}`,
        categoria,urgencia:"Média",prazo:hoje(),status:"Pendente",responsavel:"",recorrencia:"Nenhuma",
        origemAcademia:true};
      const modulos=prev.academia.modulos.map(m=>m.id!==modulo.id?m:{...m,
        aplicacoes:m.aplicacoes.map(a=>a.id===aplicacao.id?{...a,enviadaParaWork:true}:a)});
      return{...prev,nextId:id,tarefas:[...prev.tarefas,tarefa],academia:{...prev.academia,modulos}};
    });
  };

  const addBiblioteca=()=>{
    if(!novoBib.titulo.trim())return alert("Informe um título.");
    atualizarModulo({biblioteca:[...modulo.biblioteca,{...novoBib,id:Date.now(),data:hoje()}]});
    setNovoBib({titulo:"",tipo:"Link",url:"",nota:""});
  };
  const delBiblioteca=id=>atualizarModulo({biblioteca:modulo.biblioteca.filter(b=>b.id!==id)});

  const total=modulo.aulas.length;
  const feitas=modulo.aulas.filter(a=>a.concluida).length;
  const prog=total>0?Math.round((feitas/total)*100):0;

  const ABAS=[{k:"conteudo",l:`Conteúdo (${total})`},{k:"ferramentas",l:`Ferramentas (${modulo.ferramentas.length})`},
    {k:"aplicacao",l:`Aplicação (${modulo.aplicacoes.length})`},{k:"biblioteca",l:`Biblioteca (${modulo.biblioteca.length})`}];

  return(
    <div>
      <button onClick={onVoltar} style={{background:"none",border:"none",color:"#6b7280",
        fontSize:13,cursor:"pointer",padding:0,marginBottom:12,display:"flex",alignItems:"center",gap:4}}>
        ← Voltar para a Trilha
      </button>

      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
        <div>
          <div style={{fontSize:20,fontWeight:800,color:"#111"}}>{modulo.nome}</div>
          <div style={{fontSize:12,color:"#9ca3af",marginTop:2}}>{feitas}/{total} aulas concluídas</div>
        </div>
        <div style={{width:140}}>
          <div style={{height:6,background:"#f3f4f6",borderRadius:4,overflow:"hidden"}}>
            <div style={{width:`${prog}%`,height:"100%",background:"#5c2030"}}/>
          </div>
        </div>
      </div>

      <div style={{marginBottom:16}}><Tabs options={ABAS} value={aba} onChange={setAba}/></div>

      {aba==="conteudo"&&(
        total===0?<Empty msg="Nenhuma aula cadastrada ainda." icon="🎓"/>:(
          <div style={{display:"flex",flexDirection:"column",gap:8}}>
            {modulo.aulas.map(a=><LinhaAula key={a.id} aula={a} onToggle={toggleAula} onSalvarDetalhes={salvarDetalhesAula}/>)}
          </div>
        )
      )}

      {aba==="ferramentas"&&(
        <div>
          <div style={{display:"flex",justifyContent:"flex-end",marginBottom:12}}>
            <Btn onClick={()=>setModalFerramenta(true)}>+ Ferramenta</Btn>
          </div>
          {modulo.ferramentas.length===0?<Empty msg="Nenhuma ferramenta recomendada ainda." icon="🛠️"/>:(
            <div style={{display:"grid",gridTemplateColumns:"repeat(2,minmax(0,1fr))",gap:12}}>
              {modulo.ferramentas.map(f=><CardFerramenta key={f.id} f={f}/>)}
            </div>
          )}
        </div>
      )}

      {aba==="aplicacao"&&(
        <div>
          <div style={{display:"flex",gap:8,marginBottom:14}}>
            <Inp value={novaAplicacao} onChange={e=>setNovaAplicacao(e.target.value)}
              onKeyDown={e=>{if(e.key==="Enter")addAplicacao();}}
              placeholder='Ex: "Atualizar identidade visual da T11"'/>
            <Btn onClick={addAplicacao}>+ Aplicação</Btn>
          </div>
          {modulo.aplicacoes.length===0?<Empty msg="Nenhuma aplicação registrada ainda." icon="⚡"/>:(
            <div style={{display:"flex",flexDirection:"column",gap:8}}>
              {modulo.aplicacoes.map(ap=>(
                <div key={ap.id} style={{display:"flex",alignItems:"center",gap:10,padding:"10px 12px",
                  border:"1px solid #e5e7eb",borderRadius:9,background:"#fff"}}>
                  <div style={{flex:1}}>
                    <div style={{fontSize:13.5,color:"#111",fontWeight:600}}>{ap.texto}</div>
                    <div style={{fontSize:11,color:"#9ca3af",marginTop:2}}>{fmtData(ap.data)}</div>
                  </div>
                  {ap.enviadaParaWork?(
                    <span style={{fontSize:11,color:"#16a34a",fontWeight:700,flexShrink:0}}>✓ No Work</span>
                  ):(
                    <button onClick={()=>enviarParaWork(ap)} style={{background:"#f9fafb",
                      border:"1px solid #e5e7eb",borderRadius:6,padding:"5px 10px",fontSize:11.5,
                      fontWeight:700,color:"#5c2030",cursor:"pointer",flexShrink:0}}>➕ Enviar pro Work</button>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {aba==="biblioteca"&&(
        <div>
          <div style={{display:"flex",gap:8,marginBottom:14,flexWrap:"wrap"}}>
            <Inp value={novoBib.titulo} onChange={e=>setNovoBib(p=>({...p,titulo:e.target.value}))}
              placeholder="Título do material" style={{flex:1,minWidth:160}}/>
            <div style={{width:130}}>
              <Sel value={novoBib.tipo} onChange={e=>setNovoBib(p=>({...p,tipo:e.target.value}))}>
                {["Link","PDF","Documento","Template","Anotação"].map(t=><option key={t}>{t}</option>)}
              </Sel>
            </div>
            <Inp value={novoBib.url} onChange={e=>setNovoBib(p=>({...p,url:e.target.value}))}
              placeholder="Link/URL (opcional)" style={{width:200}}/>
            <Btn onClick={addBiblioteca}>+ Adicionar</Btn>
          </div>
          {modulo.biblioteca.length===0?<Empty msg="Nada guardado ainda." icon="📚"/>:(
            <div style={{display:"flex",flexDirection:"column",gap:6}}>
              {modulo.biblioteca.map(b=>(
                <div key={b.id} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 12px",
                  border:"1px solid #e5e7eb",borderRadius:9,background:"#fff"}}>
                  <span style={{fontSize:11,fontWeight:700,color:"#5c2030",background:"#faf5f6",
                    borderRadius:6,padding:"2px 8px",flexShrink:0}}>{b.tipo}</span>
                  <div style={{flex:1,minWidth:0}}>
                    {b.url?<a href={b.url} target="_blank" rel="noreferrer" style={{fontSize:13,color:"#111",
                      fontWeight:600,textDecoration:"none"}}>{b.titulo}</a>:
                      <span style={{fontSize:13,color:"#111",fontWeight:600}}>{b.titulo}</span>}
                  </div>
                  <Btn v="danger" onClick={()=>delBiblioteca(b.id)}>✕</Btn>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {modalFerramenta&&<ModalFerramenta onClose={()=>setModalFerramenta(false)} onSave={addFerramenta}/>}
    </div>
  );
}

function CardModuloAcademia({modulo,onOpen}){
  const total=modulo.aulas.length;
  const feitas=modulo.aulas.filter(a=>a.concluida).length;
  const prog=total>0?Math.round((feitas/total)*100):0;
  const concluido=total>0&&feitas===total;
  return(
    <div onClick={onOpen} style={{background:"#fff",border:`1px solid ${concluido?"#16a34a55":"#e5e7eb"}`,
      borderRadius:10,padding:"14px 16px",cursor:"pointer",transition:"all 0.15s"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
        <span style={{fontSize:13.5,fontWeight:700,color:"#111"}}>{modulo.nome}</span>
        {concluido&&<span style={{fontSize:11,color:"#16a34a",fontWeight:700}}>✓</span>}
      </div>
      <div style={{fontSize:11,color:"#9ca3af",marginBottom:8}}>{feitas}/{total} aulas · {modulo.ferramentas.length} ferramentas</div>
      <div style={{height:5,background:"#f3f4f6",borderRadius:4,overflow:"hidden"}}>
        <div style={{width:`${prog}%`,height:"100%",background:concluido?"#16a34a":"#5c2030"}}/>
      </div>
    </div>
  );
}

function PageAcademia({db,setDb}){
  const [moduloId,setModuloId]=useState(null);
  const moduloAtual=moduloId?db.academia.modulos.find(m=>m.id===moduloId):null;
  if(moduloAtual){
    return <PageModuloAcademia modulo={moduloAtual} db={db} setDb={setDb} onVoltar={()=>setModuloId(null)}/>;
  }

  const {xp,diasConsecutivos,tempoTotalMin}=db.academia;
  const nivel=calcularNivelAcademia(xp);
  const modulosConcluidos=db.academia.modulos.filter(m=>m.aulas.length>0&&m.aulas.every(a=>a.concluida)).length;
  const aplicacoesRealizadas=db.academia.modulos.reduce((a,m)=>a+m.aplicacoes.length,0);
  const horas=Math.floor(tempoTotalMin/60),mins=tempoTotalMin%60;

  return(
    <div>
      <div style={{marginBottom:16}}>
        <div style={{fontSize:22,fontWeight:800,color:"#111"}}>🎓 Academia</div>
        <div style={{fontSize:13,color:"#9ca3af"}}>Aprender → Aplicar → Medir → Melhorar → Documentar → Evoluir</div>
      </div>

      <div style={{background:"#1D1A28",borderRadius:12,padding:"18px 22px",marginBottom:16}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
          <div>
            <div style={{fontSize:11,color:"#a8a5b3",textTransform:"uppercase",letterSpacing:"0.4px"}}>Nível do Empresário</div>
            <div style={{fontSize:18,fontWeight:800,color:"#d4af37"}}>{nivel.titulo}</div>
          </div>
          <div style={{textAlign:"right"}}>
            <div style={{fontSize:11,color:"#a8a5b3"}}>{xp} XP {nivel.proximoMin?`/ ${nivel.proximoMin}`:"(nível máximo)"}</div>
          </div>
        </div>
        <div style={{height:7,background:"#2c2838",borderRadius:4,overflow:"hidden",marginBottom:16}}>
          <div style={{width:`${nivel.progresso}%`,height:"100%",background:"#d4af37"}}/>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:10}}>
          {[["🔥 Sequência",`${diasConsecutivos} dia${diasConsecutivos===1?"":"s"}`],
            ["⏱️ Tempo estudado",`${horas}h${mins.toString().padStart(2,"0")}`],
            ["✅ Módulos concluídos",`${modulosConcluidos}/${db.academia.modulos.length}`],
            ["⚡ Aplicações",aplicacoesRealizadas]].map(([lbl,val])=>(
            <div key={lbl} style={{background:"#262233",borderRadius:8,padding:"8px 10px"}}>
              <div style={{fontSize:10,color:"#a8a5b3",marginBottom:2}}>{lbl}</div>
              <div style={{fontSize:15,fontWeight:700,color:"#fff"}}>{val}</div>
            </div>
          ))}
        </div>
      </div>

      <div style={{fontSize:12,fontWeight:800,color:"#6b7280",textTransform:"uppercase",
        letterSpacing:"0.5px",marginBottom:10}}>Trilha de Evolução</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(220px,1fr))",gap:12}}>
        {db.academia.modulos.map(m=><CardModuloAcademia key={m.id} modulo={m} onOpen={()=>setModuloId(m.id)}/>)}
      </div>
    </div>
  );
}

