const MENU_PRINCIPAL=[
  {k:"central_work",l:"Central",ico:"central_work"},
  {k:"tarefas",l:"Work",ico:"tarefas"},
  {k:"dashboard",l:"Dashboard",ico:"dashboard"},
  {k:"pedidos",l:"Pedidos",ico:"pedidos"},
];
const MENU_GESTAO=[
  {k:"crm",l:"CRM",ico:"crm"},
  {k:"estoque",l:"Estoque",ico:"estoque"},
  {k:"ecossistema",l:"Ecossistema",ico:"ecossistema"},
];
const MENU_FINANCEIRO=[
  {k:"custo",l:"Custo / Lucro",ico:"custo"},
  {k:"caixa",l:"Caixa",ico:"caixa"},
];
const MENU_FORMACAO=[
  {k:"academia",l:"Academia",ico:"academia"},
];

function MenuItem({item,active,onClick,escuro}){
  const [h,setH]=useState(false);
  const corAtivo = "#5c2030"; // bordô discreto, cor de marca do menu
  // A barra lateral é sempre escura (identidade fixa do app), então o texto/hover
  // do menu seguem sempre o estilo "escuro", não o tema claro/escuro do conteúdo.
  const bg = active ? corAtivo : (h ? "rgba(255,255,255,0.08)" : "transparent");
  const txt = active ? "#fff" : "#c4c1cc";
  return(
    <div onClick={onClick} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)}
      style={{display:"flex",alignItems:"center",gap:9,padding:"6px 12px",cursor:"pointer",
        borderRadius:8,margin:"1px 8px",background:bg,transition:"all 0.15s"}}>
      <MenuIco k={item.ico} active={active}/>
      <span style={{fontSize:12.5,fontWeight:active?700:500,color:txt,whiteSpace:"nowrap",
        overflow:"hidden",textOverflow:"ellipsis"}}>{item.l}</span>
    </div>
  );
}

function MenuLabel({children}){
  return<div style={{fontSize:9.5,fontWeight:800,color:"#6b6877",textTransform:"uppercase",
    letterSpacing:"0.6px",padding:"7px 14px 3px"}}>{children}</div>;
}

function Sidebar({page,setPage,onLogout,open,onCloseMobile,escuro,setEscuro}){
  const ir=k=>{setPage(k);onCloseMobile&&onCloseMobile();};
  const [hDark,setHDark]=useState(false);
  // A barra lateral é sempre escura — identidade fixa do app, não depende do
  // Modo Escuro (que afeta só o conteúdo da direita).
  return(
    <div style={{width:172,minWidth:172,background:"#17151F",borderRight:"1px solid #24212e",
      display:"flex",flexDirection:"column",height:"100vh",flexShrink:0,overflowY:"auto"}}>
      <div style={{padding:"12px 12px 10px",borderBottom:"1px solid #24212e"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <div style={{lineHeight:1.2,display:"flex",flexDirection:"column",justifyContent:"center",minWidth:0}}>
            <img src={LOGO_T11_WORDMARK} alt="T11 Sports" style={{height:28,width:"auto",objectFit:"contain",display:"block"}}/>
          </div>
        </div>
      </div>
      <div style={{flex:1,padding:"4px 0"}}>
        <MenuLabel>Principal</MenuLabel>
        {MENU_PRINCIPAL.map(it=><MenuItem key={it.k} item={it} active={page===it.k} onClick={()=>ir(it.k)}/>)}
        <MenuLabel>Gestão</MenuLabel>
        {MENU_GESTAO.map(it=><MenuItem key={it.k} item={it} active={page===it.k} onClick={()=>ir(it.k)}/>)}
        <MenuLabel>Financeiro</MenuLabel>
        {MENU_FINANCEIRO.map(it=><MenuItem key={it.k} item={it} active={page===it.k} onClick={()=>ir(it.k)}/>)}
        <MenuLabel>Formação</MenuLabel>
        {MENU_FORMACAO.map(it=><MenuItem key={it.k} item={it} active={page===it.k} onClick={()=>ir(it.k)}/>)}
        <MenuLabel>Sistema</MenuLabel>
        <div onClick={()=>setEscuro(e=>!e)} onMouseEnter={()=>setHDark(true)} onMouseLeave={()=>setHDark(false)}
          style={{display:"flex",alignItems:"center",gap:9,padding:"6px 12px",cursor:"pointer",
            borderRadius:8,margin:"1px 8px",
            background:hDark?"rgba(255,255,255,0.08)":"transparent",transition:"all 0.15s"}}>
          <span style={{fontSize:15,width:16,display:"inline-flex",justifyContent:"center"}}>🌙</span>
          <span style={{fontSize:12.5,fontWeight:500,color:"#c4c1cc",flex:1}}>Modo Escuro</span>
          <div style={{width:30,height:16,borderRadius:10,background:escuro?"#5c2030":"#3a3744",
            position:"relative",transition:"all 0.2s",flexShrink:0}}>
            <div style={{width:12,height:12,borderRadius:"50%",background:"#fff",position:"absolute",
              top:2,left:escuro?16:2,transition:"all 0.2s",boxShadow:"0 1px 3px rgba(0,0,0,0.3)"}}/>
          </div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:9,padding:"6px 12px",margin:"1px 8px 4px"}}>
          <div style={{width:22,height:22,borderRadius:"50%",background:"#5c2030",color:"#fff",
            display:"flex",alignItems:"center",justifyContent:"center",fontWeight:800,fontSize:10.5,
            flexShrink:0}}>F</div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:12,fontWeight:700,color:"#fff",whiteSpace:"nowrap",
              overflow:"hidden",textOverflow:"ellipsis"}}>Fabrício</div>
            <div style={{fontSize:9.5,color:"#8a8794"}}>Administrador</div>
          </div>
          <button onClick={onLogout} title="Sair"
            style={{border:"none",background:"none",cursor:"pointer",padding:4,borderRadius:6,
              display:"flex",color:"#8a8794",flexShrink:0}}>
            <Ico path={ICONS.logout} size={15}/>
          </button>
        </div>
      </div>
    </div>
  );
}

const PAGE_TITLES={
  dashboard:"Dashboard", central_work:"Central", estoque:"Estoque", pedidos:"Pedidos", crm:"CRM",
  custo:"Custo / Lucro", caixa:"Caixa", tarefas:"Work", fornecedor:"Fornecedores", ecossistema:"Ecossistema",
  academia:"Academia",
};

function Topbar({page,busca,setBusca,onRefresh,escuro}){
  const [girando,setGirando]=useState(false);
  const refresh=()=>{setGirando(true);onRefresh&&onRefresh();setTimeout(()=>setGirando(false),500);};
  return(
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:16,
      padding:"16px 22px",borderBottom:escuro?"1px solid #24242e":"1px solid #e5e7eb",
      background:escuro?"#13131a":"#fff",position:"sticky",top:0,zIndex:50}}>
      <div style={{display:"flex",alignItems:"center",gap:10,minWidth:0}}>
        <div style={{width:4,height:20,background:"#5c2030",borderRadius:2}}/>
        <span style={{fontSize:17,fontWeight:800,color:escuro?"#fff":"#111",whiteSpace:"nowrap"}}>{PAGE_TITLES[page]||""}</span>
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10,flex:1,justifyContent:"flex-end"}}>
        <div style={{position:"relative",width:240,maxWidth:"40vw"}}>
          <div style={{position:"absolute",left:11,top:0,bottom:0,display:"flex",alignItems:"center",color:"#9ca3af"}}>
            <Ico path={ICONS.search} size={15}/>
          </div>
          <input value={busca} onChange={e=>setBusca(e.target.value)} placeholder="Buscar pedidos, produtos..."
            style={{...INP,paddingLeft:34,fontSize:12.5,
              background:escuro?"#1c1c26":"#fff",borderColor:escuro?"#2e2e3a":"#d1d5db",
              color:escuro?"#e5e7eb":"#111"}}/>
        </div>
        <button onClick={refresh} title="Atualizar"
          style={{display:"flex",alignItems:"center",gap:6,padding:"8px 12px",borderRadius:8,
            border:escuro?"1px solid #2e2e3a":"1px solid #d1d5db",background:escuro?"#1c1c26":"#fff",
            cursor:"pointer",fontSize:12,fontWeight:700,
            color:escuro?"#cbd5e1":"#374151",whiteSpace:"nowrap"}}>
          <span style={{display:"flex",transition:"transform 0.5s",transform:girando?"rotate(360deg)":"none"}}>
            <Ico path={ICONS.refresh} size={15}/>
          </span>
          Atualizar
        </button>
        <div style={{display:"flex",alignItems:"center",gap:7,padding:"6px 10px 6px 8px",
          borderRadius:20,background:escuro?"#1c1c26":"#f9fafb",border:escuro?"1px solid #2e2e3a":"1px solid #e5e7eb"}}>
          <span style={{width:8,height:8,borderRadius:"50%",background:"#16a34a"}}/>
          <span style={{fontSize:12,fontWeight:700,color:escuro?"#cbd5e1":"#374151"}}>Fabrício</span>
        </div>
      </div>
    </div>
  );
}

// ── BUSCA GLOBAL (filtra produtos/pedidos pelo termo do topo) ──
function useBuscaGlobal(db,busca){
  return useMemo(()=>{
    if(!busca||!busca.trim())return null;
    const t=busca.toLowerCase();
    const produtos=db.produtos.filter(p=>(p.time||p.nome||"").toLowerCase().includes(t)||(p.cor||"").toLowerCase().includes(t));
    const pedidos=db.pedidos.filter(p=>(p.cliente||"").toLowerCase().includes(t)||(p.time||p.camisa||"").toLowerCase().includes(t));
    return{produtos,pedidos};
  },[db,busca]);
}

function BuscaResultados({resultado,onClose}){
  if(!resultado)return null;
  const total=resultado.produtos.length+resultado.pedidos.length;
  return(
    <div style={{margin:"0 28px 16px"}}>
      <Alert type="info">
        🔎 <strong>{total}</strong> resultado{total!==1?"s":""} encontrado{total!==1?"s":""}
        {total>0&&<span> — {resultado.produtos.length} produto(s), {resultado.pedidos.length} pedido(s)</span>}
        <button onClick={onClose} style={{marginLeft:"auto",border:"none",background:"none",
          cursor:"pointer",fontWeight:700,color:"#2563eb",fontSize:12}}>Limpar busca</button>
      </Alert>
    </div>
  );
}

// ── APP PRINCIPAL ────────────────────────────────────────────
export default function App(){
  const [logado,setLogado]=useState(()=>{try{return localStorage.getItem("t11_logado")==="1";}catch(_){return false;}});
  const [db,setDb]=useState(loadDB);
  const [page,setPage]=useState("dashboard");
  const [statusFiltroPedidos,setStatusFiltroPedidos]=useState(null);
  const [mesFiltroPedidos,setMesFiltroPedidos]=useState(null);

  const navegarPara=(novaPagina,status,mes)=>{
    setStatusFiltroPedidos(status||null);
    setMesFiltroPedidos(mes||null);
    setPage(novaPagina);
  };
  const [busca,setBusca]=useState("");
  const [modalPedido,setModalPedido]=useState(null);
  const [modalProduto,setModalProduto]=useState(null);
  const [escuro,setEscuro]=useState(()=>{try{return localStorage.getItem("t11_escuro")==="1";}catch(_){return false;}});

  useEffect(()=>{try{localStorage.setItem("t11_escuro",escuro?"1":"0");}catch(_){}},[escuro]);

  useEffect(()=>{saveDB(db);},[db]);

  // Motor de missões automáticas: outros módulos (Pedidos, Estoque, CRM) geram
  // tarefas no Work sozinhos quando algo relevante acontece. Cada regra só
  // dispara uma vez por evento (checagem por origemKey dentro de setDb, contra
  // o estado mais atual — nunca duplica).
  useEffect(()=>{
    const propostas=gerarMissoesAutomaticas(db);
    if(propostas.length===0)return;
    setDb(prev=>{
      const faltantes=propostas.filter(p=>!prev.tarefas.some(t=>t.origemKey===p.origemKey));
      if(faltantes.length===0)return prev;
      let id=prev.nextId;
      const comId=faltantes.map(t=>({...t,id:++id}));
      return{...prev,nextId:id,tarefas:[...prev.tarefas,...comId]};
    });
  },[db]);

  // Garante que a página ocupe 100% da tela e role corretamente,
  // sem precisar editar o index.html/CSS global do projeto.
  useEffect(()=>{
    const id="t11-global-reset";
    if(document.getElementById(id))return;
    const style=document.createElement("style");
    style.id=id;
    style.textContent=`
      html,body{margin:0;padding:0;height:100%;width:100%;overflow:hidden;text-align:left;}
      #root,#app,body>div:first-child{height:100%;width:100%;text-align:left;}
      *{box-sizing:border-box;}
    `;
    document.head.appendChild(style);
  },[]);

  const resultadoBusca=useBuscaGlobal(db,busca);

  const login=()=>{try{localStorage.setItem("t11_logado","1");}catch(_){}setLogado(true);};
  const logout=()=>{if(!window.confirm("Deseja sair?"))return;try{localStorage.removeItem("t11_logado");}catch(_){}setLogado(false);};

  if(!logado)return <Login onLogin={login}/>;

  const addPedido=()=>setModalPedido({modo:"novo"});
  const editPedido=p=>setModalPedido({modo:"editar",item:p});
  const delPedido=id=>{if(!window.confirm("Excluir pedido?"))return;setDb(prev=>({...prev,pedidos:prev.pedidos.filter(p=>p.id!==id)}));};
  const salvarPedido=f=>{
    const modoNovo=modalPedido?.modo!=="editar";
    setDb(prev=>{
      if(!modoNovo)return{...prev,pedidos:prev.pedidos.map(p=>p.id===f.id?f:p)};
      const id=prev.nextId+1;
      let produtos=prev.produtos;
      if(f.vendaEstoque&&f.produtoEstoqueId){
        produtos=prev.produtos.map(p=>p.id===f.produtoEstoqueId?{...p,qtd:Math.max(0,p.qtd-(f.qtd||1))}:p);
      }
      return{...prev,nextId:id,pedidos:[...prev.pedidos,{...f,id}],produtos};
    });
    // CRM: pedido novo pra um cliente que ainda não existe lá → oferece cadastrar
    // com o que já foi digitado agora, sem pedir pra digitar tudo de novo.
    if(modoNovo&&f.cliente&&!isEstoque(f)){
      const existe=db.clientes.some(c=>clienteCorrespondePedido(c,f));
      if(!existe&&window.confirm(`Cliente "${f.cliente}" ainda não está no CRM. Deseja cadastrar agora?`)){
        setDb(prev=>{
          const id=(prev.clientes.reduce((m,c)=>Math.max(m,c.id),0)||0)+1;
          const novo={id,nome:f.cliente,telefone:f.telefone||"",cidade:"",instagram:"",observacoes:"",
            origem:"Outro",status:"Ativo",creditoLimite:0,valorEmAberto:0,situacaoPagamento:"Neutro",
            estagioComercial:"Cliente",
            criadoEm:hoje(),timeline:[{id:1,data:hoje(),texto:"Cliente cadastrado a partir de um pedido"}]};
          return{...prev,clientes:[...prev.clientes,novo]};
        });
      }
    }
    setModalPedido(null);
  };
  const updateMeta=m=>setDb(prev=>({...prev,meta:m}));

  const addProduto=()=>setModalProduto({modo:"novo"});
  const editProduto=p=>setModalProduto({modo:"editar",item:p});
  const delProduto=id=>{if(!window.confirm("Excluir produto?"))return;setDb(prev=>({...prev,produtos:prev.produtos.filter(p=>p.id!==id)}));};
  const salvarProduto=f=>{
    setDb(prev=>{
      if(modalProduto?.modo==="editar")return{...prev,produtos:prev.produtos.map(p=>p.id===f.id?f:p)};
      const id=prev.nextId+1;return{...prev,nextId:id,produtos:[...prev.produtos,{...f,id}]};
    });
    setModalProduto(null);
  };

  const renderPage=()=>{
    switch(page){
      case "dashboard": return <PageDashboard db={db} setDb={setDb} onNavigate={navegarPara}/>;
      case "central_work": return <PageCentralWork db={db} setDb={setDb} onNavigate={navegarPara}/>;
      case "estoque": return <PageEstoque db={db} onAdd={addProduto} onEdit={editProduto} onDelete={delProduto}/>;
      case "pedidos": return <PagePedidos db={db} onAdd={addPedido} onEdit={editPedido} onDelete={delPedido} onUpdateMeta={updateMeta} statusInicial={statusFiltroPedidos} mesInicial={mesFiltroPedidos}/>;
      case "crm": return <PageCRM db={db} setDb={setDb} onNavigate={navegarPara}/>;
      case "custo": return <PageCusto db={db} setDb={setDb}/>;
      case "caixa": return <PageCaixa db={db} setDb={setDb}/>;
      case "tarefas": return <PageTarefas db={db} setDb={setDb}/>;
      case "fornecedor": return <PageFornecedor db={db} setDb={setDb}/>;
      case "ecossistema": return <PageEcossistema db={db} setDb={setDb}/>;
      case "academia": return <PageAcademia db={db} setDb={setDb}/>;
      default: return null;
    }
  };

  return(
    <div style={{display:"flex",width:"100%",height:"100vh",overflow:"hidden",
      background:escuro?"#0b0b0f":"#F5F6FA",
      fontFamily:"-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif"}}>
      <Sidebar page={page} setPage={setPage} onLogout={logout} escuro={escuro} setEscuro={setEscuro}/>
      <div style={{flex:"1 1 auto",minWidth:0,width:"100%",display:"flex",flexDirection:"column",
        height:"100vh",overflowY:"auto"}}>
        <Topbar page={page} busca={busca} setBusca={setBusca} onRefresh={()=>setDb(loadDB())} escuro={escuro}/>
        <BuscaResultados resultado={resultadoBusca} onClose={()=>setBusca("")}/>
        <div style={{padding:"20px 22px 40px",flex:1,width:"100%",boxSizing:"border-box"}}>
          {renderPage()}
        </div>
      </div>

      {modalPedido&&(
        <Modal title={modalPedido.modo==="editar"?`Editar Pedido #${modalPedido.item?.id}`:"Novo Pedido"} onClose={()=>setModalPedido(null)} wide>
          <FormPedido inicial={modalPedido.item} produtos={db.produtos}
            onSave={salvarPedido} onClose={()=>setModalPedido(null)}/>
        </Modal>
      )}
      {modalProduto&&(
        <Modal title={modalProduto.modo==="editar"?"Editar Produto":"Novo Produto"} onClose={()=>setModalProduto(null)} wide>
          <FormProduto inicial={modalProduto.item}
            onSave={salvarProduto} onClose={()=>setModalProduto(null)}/>
        </Modal>
      )}
    </div>
  );
}
